comms.text:
@1 וַחֲזָא בָּלָק בַּר צִפּוֹר יָת כָּל דִי עֲבַד יִשְׂרָאֵל לֶאֱמוֹרָאֵי:
@2 וּדְחִיל מוֹאֲבָאָה מִן קֳדָם עַמָא לַחֲדָא אֲרֵי סַגִי הוּא וַעֲקַת לְמוֹאֲבָאָה מִן קֳדָם בְּנֵי יִשְׂרָאֵל:
@3 וַאֲמַר מוֹאָב לְסָבֵי מִדְיָן כְּעַן יְשֵׁיצוּן קְהָלָא יָת כָּל סַחֲרָנָנָא כְּמָא דִמְלַחֵיךְ תּוֹרָא יָת יְרוֹקָא דְחַקְלָא וּבָלָק בַּר צִפּוֹר מַלְכָּא לְמוֹאָב בְּעִידָנָה הַהִיא:
@4 וּשְׁלַח אִזְגַדִין לְוָת בִּלְעָם בַּר בְּעוֹר לִפְּתוֹר אֲרָם דְעַל פְּרָת אֲרַע בְּנֵי עַמֵיהּ לְמִקְרֵי לֵיהּ לְמֵימָר הָא עַמָא נְפַק מִמִצְרַיִם הָא חֲפָא יַת עֵין שִׁמְשָׁא דְאַרְעָא וְהוּא שָׁרֵי מִלְקִבְלִי:
@5 וּכְעַן אִיתָא כְּעַן לוֹט לִי יָת עַמָא הָדֵין אֲרֵי תַקִיף הוּא מִנִי מָאִים אֵכוּל לְאַגָחָא בֵּיהּ קְרָב וַאֲתָרֵכִינֵיהּ מִן אַרְעָא אֲרֵי יְדַעֲנָא יָת דִי תְבָרַךְ מְבָרָךְ וְדִי תְלוֹט לִיט:
@6 וַאֲזָלוּ סָבֵי מוֹאָב וְסָבֵי מִדְיָן וְקִסְמַיָא בִּידֵיהוֹן וַאֲתוֹ לְוַת בִּלְעָם וּמַלִילוּ עִמֵיהּ פִּתְגָמֵי בָּלָק:
@7 וַאֲמַר לְהוֹן בִּיתוּ הָכָא בְּלֵילְיָא וְאָתֵב יַתְכוֹן פִּתְגָמָא כְּמָא דִי יְמַלֵיל יְיָ עִמִי וְאוֹרִיכוּ רַבְרְבֵי מוֹאָב עִם בִּלְעָם:
@8 וַאֲתָא מֵימַר מִן קֳדָם יְיָ לְוַת בִּלְעָם וַאֲמַר מָן גוּבְרַיָא הָאִלֵין דְעִמָךְ:
@9 וַאֲמַר בִּלְעָם קֳדָם יְיָ בָּלָק בַּר צִפּוֹר מַלְכָּא דְמוֹאָב שְׁלַח לְוָתִי:
@10 הָא עַמָא דִי נְפַק מִמִצְרַיִם וַחֲפָא יָת עֵין שִׁמְשָׁא דְאַרְעָא כְּעַן אִיתָא לוֹט לִי יָתֵיהּ מָאִים אֵיכוּל לְאַגָחָא בֵּיהּ קְרָב וְאֲתָרֵיכִינֵיהּ:
@11 וַאֲמַר יְיָ לְבִלְעָם לָא תֵיזִיל עִמְהוֹן לָא תְלוֹט יָת עַמָא אֲרֵי בְרִיךְ הוּא:
@12 וְקָם בִּלְעָם בְּצַפְרָא וַאֲמַר לְרַבְרְבֵי בָלָק אִיזִילוּ לְאַרְעֲכוֹן אֲרֵי לֵית רַעֲוָא קֳדָם יְיָ לְמִשְׁבְּקִי לְמֵיזַל עִמְכוֹן:
@13 וְקָמוּ רַבְרְבֵי מוֹאָב וַאֲתוֹ לְוָת בָּלָק וַאֲמָרוּ סָרֵיב בִּלְעָם לְמֵיתֵי עִמָנָא:
@14 וְאוֹסִיף עוֹד בָּלָק לְמִשְׁלַח רַבְרְבִין סַגִיאִין:ויַקִירִין מֵאִלֵין:
@15 וַאֲתוֹ לְוָת בִּלְעָם וַאֲמָרוּ לֵיהּ כִּדְנַן אֲמַר בָּלָק בַּר צִפּוֹר לָא כְעַן תִּתְמְנַע מִלְמֵיתֵי לְוָתִי:
@16 אֲרֵי יְקָרָא אֲיַקְרִינָךְ לַחֲדָא וְכֹל דִי תֵימַר לִי אַעְבֵּד וְאִיתָא כְעַן לוֹט לִי יַת עַמָא הָדֵין:
@17 וַאֲתֵיב בִּלְעָם וַאֲמַר לְעַבְדֵי בָלָק אִם יִתֶּן לִי בָלָק מְלֵי בֵיתֵיהּ כְּסַף וּדְהַב לֵית לִי רְשׁוּ לְמֶעֱבַּר עַל גְזֵירַת מֵימְרָא דַיְיָ אֱלָהָי לְמֶעְבַּד זְעֵרְתָּא אוֹ רַבְּתָא:
@18 וּכְעַן אוֹרִיכוּ כְעַן הָכָא אַף אַתּוּן בְּלֵילְיָא וְאִדַע מָה יוֹסֵף יְיָ לְמַלָלָא עִמִי:
@19 וַאֲתָּא מֵימַר מִן קֳדָם יְיָ לְבִלְעָם בְּלֵילְיָא וַאֲמַר לֵיהּ אִם לְמִקְרֵי לָךְ אֲתוֹ גֻבְרַיָא קוּם אִיזֵיל עִמְהוֹן וּבְרַם יַת פִּתְגָמָא דִי אֲמַלֵיל עִמָךְ יָתֵיהּ תַּעְבֵיד:
@20 וְקָם בִּלְעָם בְּצַפְרָא וְזָרֵיז יַת אֲתָנֵיהּ וַאֲזַל עִם רַבְרְבֵי מוֹאָב:
@21 וּתְקֵיף רָגְזָא דַיְיָ אֲרֵי אָזֵיל הוּא וְאִתְעַתַּד מַלְאָכָא דַיְיָ בְּאוֹרְחָא לְשָׂטָן לֵהּ וְהוּא רָכִיב עַל אַתָּנֵיהּ וּתְרֵין עוּלֵימוֹהִי עִמֵהּ:
@22 וַחֲזַת אֲתָּנָא יַת מַלְאָכָא דַיְיָ מְעַתַּד בְּאָרְחָא וְחַרְבֵּיהּ שְׁלִיפָא בִּידֵיהּ וּסְטַת אֲתָּנָא מִן אוֹרְחָא וַאֲזָלַת בְּחַקְלָא וּמְחָא בִּלְעָם יַת אֲתָּנָא לְאַסְטָיוּתַהּ לְאָרְחָא:
@23 וְקָם מַלְאָכָא דַיְיָ בִּשְׁבִיל כַּרְמַיָא אַתְרָא דְגָדֵירָא מִכָּא וְגָדֵירָא מִכָּא:
@24 וַחֲזַת אֲתָּנָא יַת מַלְאָכָא דַיְיָ וְאִדְחֵיקַת לְכָתְלָא וּדְחֵיקַת יַת רִגְלָא דְבִלְעָם לְכָתְלָא וְאוֹסִיף לְמִמְחַהּ:
@25 וְאוֹסֵף מַלְאָכָא דַיְיָ לְמֶעְבָּר וְקָם בַּאֲתַר עָק דִי לֵית אֹרַח לְמִסְטֵי לְיַמִינָא וְלִשְׂמָאלָא:
@26 וַחֲזַת אֲתָּנָא יַת מַלְאָכָא דַיְיָ וּרְבָעַת תְּחוֹת בִּלְעָם וּתְקֵיף רוּגְזָא דְבִלְעָם וּמְחָא יַת אֲתָּנָא בְּחֻטְרָא:
@27 וּפְתַח יְיָ יַת פּוּמָא דַאֲתָּנָא וַאֲמָרַת לְבִּלְעָם מָה עֲבָדִית לָךְ אֲרֵי מְחִיתַנִי דְנַן תְּלַת זִמְנִין:
@28 וַאֲמַר בִּלְעָם לַאֲתָּנָא אֲרֵי חַיִיכְתְּ בִּי אִלוּפוֹן אִית חַרְבָּא בִּידִי אֲרֵי כְעָן קְטַלְתִּיךְ:
@29 וַאֲמָרַת אֲתָּנָא לְבִלְעָם הֲלָא אֲנָא אֲתָּנָךְ דְרָכַבְתְּ עֲלַי מִדְאִיתָךְ עַד יוֹמָא הָדֵין הֲמֵילַף אַלִפְנָא לְמֶעֱבַּד לָךְ כְּדֵין וַאֲמַר לָא:
@30 וּגְלָא יְיָ יַת עֵינֵי בִלְעָם וַחֲזָא יַת מַלְאָכָא דַיְיָ מְעַתַּד בְּאָרְחָא וְחַרְבֵּיהּ שְׁלִיפָא בִידֵיהּ וּכְרַע וּסְגִיד לְאַפּוֹהִי:
@31 וַאֲמַר לֵיהּ מַלְאָכָא דַיְיָ עַל מָה מָחִיתָא יַת אֲתָּנָךְ דְנַן תְּלַת זִמְנִין הָא אֲנָא נְפָקִית לְמִשְׂטַן אֲרֵי גְלֵי קֳדָמַי דְאַתְּ רָעֵי לְמֵיזַל בְּאוֹרְחָא לְקִבְּלִי:
@32 וַחֲזַתְנִי אֲתָּנָא וּסְטַת מִן קֳדָמַי דְנַן תְּלַת זִמְנִין אִילוּפוֹן לָא סְטַּת מִן קֳדָמַי אֲרֵי כְעַן אַף יָתָךְ קְטָלִית וְיָתַהּ קַיֵימִית:
@33 וַאֲמַר בִּלְעָם לְמַלְאָכָה דַיְיָ חָבִית אֲרֵי לָא יְדָעִית אֲרֵי אַתְּ מְעַתֵּד לָקֳדָמוּתִי בְּאָרְחָא וּכְעַן אִם בִּישׁ בְּעֵינָךְ אֵיתוּב לִי:
@34 וַאֲמַר מַלְאָכָא דַיְיָ לְבִלְעָם אִיזֵיל עִם גוּבְרַיָא וּלְחוֹד יַת פִּתְגָמָא דִי אֲמַלֵיל עִמָךְ יָתֵיהּ תְּמַלֵיל וַאֲזַל בִּלְעָם עִם רַבְרְבֵי בָּלָק:
@35 וּשְׁמַע בָּלָק אֲרֵי אָתָא בִלְעָם וּנְפַק לָקֳדָמוּתֵה לְקַרְתָּא דְמוֹאָב דִי עַל תְּחוּם אַרְנוֹן דִי בִּסְטַר תְּחוּמָא:
@36 וַאֲמַר בָּלָק לְבִלְעָם הֲלָא מִשְׁלַח שַׁלְחִית לְוָתָךְ לְמִקְרֵי לָךְ לְמָא לָא אֲתֵיתָא לְוָתִי הַבְקוּשְׁטָא הֲוֵיתָא אָמַר לֵית אֲנָא יָכִיל לְיַקְרוּתָךְ:
@37 וַאֲמַר בִּלְעָם לְבָלָק הָא אֲתֵיתִי לְוָתָךְ כְּעַן הֲמֵיכַל יְכִלְנָא לְמַלָלָא מִדַעַם פִּתְגָמָא דִי יְשַׁוֵי יְיָ בְּפוּמִי יָתֵיהּ אֲמַלֵיל:
@38 וַאֲזַל בִּלְעָם עִם בָּלָק וַאֲתוֹ לְקִרְיַת מְחוֹזוֹהִי:
@39 וּנְכֵיס בָּלָק תּוֹרִין וְעָאן וּשְׁלַח לְבִלְעָם וּלְרַבְרְבַיָא דִי עִמֵיהּ:
@40 וַהֲוָה בְּצַפְרָא וּדְבַר בָּלָק יַת בִּלְעָם וְאַסְקֵיהּ לְרָמַת דַחַלְתֵּיהּ וַחֲזָא מִתַּמָן קְצַת מִן עַמָא:
@41 וַאֲמַר בִּלְעָם לְבָלָק בְּנֵה לִי הָכָא שַׁבְעָא מַדְבְּחִין וְאַתְקִין לִי הָכָא שַׁבְעָא תוֹרִין וְשַׁבְעָא דִכְרִין:
@42 וַעֲבַד בָּלָק כְּמָא דִי מַלֵיל בִּלְעָם וְאַסֵיק בָּלָק וּבִלְעָם תּוֹר וּדְכַר עַל כָּל מַדְבְּחָא:
@43 וַאֲמַר בִּלְעָם לְבָלָק אִתְעַתֵּד עַל עֲלָתָךְ וְאֵיהַךְ מָאִים יְעָרַע מֵימַר מִן קֳדָם יְיָ לָקֳדָמוּתִי וּפִתְגָמָא דְיַחֲזִנַנִי וְאֵחַוֵי לָךְ וַאֲזַל יְחִידִי:
@44 וְעָרַע מֵימַר מִן קֳדָם יְיָ לְוַת בִּלְעָם וַאֲמַר לֵיהּ יַת שַׁבְעָא מַדְבְּחִין סְדָרִית וְאַסֵקִית תּוֹר וּדְכַר עַל כָּל מַדְבְּחָא:
@45 וְשַׁוִי יְיָ פִּתְגָמָא בְּפוּמָא דְבִלְעָם וַאֲמַר תּוּב לְוַת בָּלָק וּכְדֵין תְּמַלֵיל:
@46 וְתַב לְוָתֵיהּ וְהָא מְעַתֵּד עַל עֲלָתֵיהּ הוּא וְכָל רַבְרְבֵי מוֹאָב:
@47 וּנְטַל מַתְלֵיהּ וַאֲמַר מִן אֲרָם דַבְּרַנִי בָלָק מַלְכָּא דְמוֹאָב מִטוּרֵי מַדִנְחָא אִיתָא לוֹטּ לִי יַעֲקֹב וְאִיתָא תָּרֵיךְ לִי יִשְׂרָאֵל:
@48 מָה אֲלוֹטֵיהּ דְלָא לַטְיֵהּ אֵל וּמָה אֲתָרְכֵיהּ דְלָא תָרְכֵיהּ יְיָ:
@49 אֲרֵי מֵרֵישׁ טוּרַיָא חֲזִיתֵיהּ וּמֵרָמָתָא סְכִיתֵיהּ הָא עַמָא בִּלְחוֹדֵיהוֹן עֲתִידִין דְיַחְסְנוּן עַלְמָא וּבְעַמְמַיָא לָא יִתְדְנוּן גְמִירָא:
@50 מָן יֵיכוֹל לְמִמְנֵי דַעַדְקַיָא דְבֵית יַעֲקֹב דְאָמִיר עֲלֵיהוֹן יִסְגוּן כְּעַפְרָא דְאַרְעָא אוֹ חֲדָא מֵאַרְבַּע מַשִׁרְיָתָא דְיִשְׂרָאֵל תְּמוּת נַפְשִׁי מוֹתָא דְקַשִׁיטוֹהִי וּתְהֵי סוֹפִי כְּוַתְהוֹן:
@51 וַאֲמַר בָּלָק לְבִלְעָם מֶה עֲבַדְתָּא לִי לְמֵילַט סַנְאַי דְבַרְתִּיךְ וְהָא בְּרָכָא מְבָרְכַת לְהוֹן:
@52 וַאֲתֵיב וַאֲמַר הֲלָא יָת דִי יְשַׁוֵי יְיָ בְּפוּמִי יָתֵיהּ אֶטַר לְמַלָלָא:
@53 וַאֲמַר לֵיהּ בָּלָק אִיתָא כְעַן עִמִי לַאֲתַר אוֹחֲרָן דְתֶחֱזִנֵיהּ מִתַּמָן לְחוֹד קְצָתֵיהּ תֶּחֱזֵי וְכוּלֵיהּ לָא תֶחֱזֵי וּתְלוּטֵיהּ לִי מִתַּמָן:
@54 וְדַבְּרֵיהּ לַחֲקַל סְכוּתָא לְרֵישׁ רָמָתָא וּבְנָא שַׁבְעָא מַדְבְּחִין וְאַסֵיק תּוֹר וּדְכַר עַל כָּל מַדְבְּחָא:
@55 וַאֲמַר לְבָלָק אִתְעַתֵּד הָכָא עַל עֲלָתָךְ וַאֲנָא אִתְמְטֵי עַד כָּא:
@56 וְעָרַע מֵימַר מִן קֳדָם יְיָ לְבִלְעָם וְשַׁוִי פִתְגָמָא בְּפוּמֵיהּ וַאֲמַר תּוּב לְוָת בָּלָק וּכְדֵין תְּמַלֵיל:
@57 וַאֲתָא לְוָתֵיהּ וְהוּא מְעַתַּד עַל עֲלָתֵיהּ וְרַבְרְבֵי מוֹאָב עִמֵיהּ וַאֲמַר לֵיהּ בָּלָק מָה מַלִיל יְיָ:
@58 וּנְטַל מַתְלֵיהּ וַאֲמַר קוּם בָּלָק וּשְׁמַע אָצִית לְמֵימְרִי בַּר צִפֹּר:
@59 לָא כְמִלֵי בְּנֵי אֱנָשָׁא מֵימַר אֱלָהָא בְּנֵי אֱנָשָׁא אָמְרִין וּמְכַדְבִין וְאַף לָא כְעוֹבָדֵי בְּנֵי בִּשְׂרָא דְאִינוּן גָזְרִין לְמֶעְבַּד וְתַיְבִין וּמִתְמַלְכִין דְהוּא אָמַר וְעָבֵיד וְכָל מֵימְרֵהּ מִתְקַיָם:
@60 הָא בִּרְכָן קַבֵּילִית וַאֲבָרֵכִינֵיהּ לְיִשְׂרָאֵל וְלָא אָתֵב בִּרְכְּתִי מִינֵיה:
@61 אִסְתַּכָּלִית לֵית פָּלְחֵי גִלוּלִין בִּדְבֵית יַעֲקֹב וְאַף לָא עָבְדֵי לֵיאוּת שְׁקַר בְּיִשְׂרָאֵל מֵימְרָא דַיְיָ אֱלָהָהוֹן בְּסַעְדְהוֹן וּשְׁכִינַת מַלְכְּהוֹן בֵּינֵיהוֹן:
@62 אֱלָהָא דְאַפֵּקִנוּן מִמִצְרָיִם תּוּקְפָא וְרוּמָא דִילֵיהּ:
@63 אֲרֵי לָא נַחֲשַׁיָא צָבָן דְיִיטַב לִדְבֵית יַעֲקֹב וְאַף לָא קְסָמַיָא רְעַן בִּרְבוּת בֵּית יִשְׂרָאֵל כְּעִדַן יִתְאַמַר לְיַעֲקֹב וּלְיִשְׂרָאֵל מָה עֲבַד אֱלָהָא:
@64 הָא עַמָא כְּלֵיתָא שָׁרֵי וּכְאַרְיָא יִתְנַטֵל לָא יִשְׁרֵי בְאַרְעֵיהּ עַד דְיִקְטוֹל קְטוֹל וְנִכְסֵי עֲמְמַיָא יֵירָת:
@65 וַאֲמַר בָּלָק לְבִלְעָם אַף מֵילַט לָא תְלוּטִּינוּן אַף בְּרָכָא לָא תְבָ רֵ כִ י נוּ ן:
@66 וַאֲתֵיב בִּלְעָם וַאֲמַר לְבָלָק הֲלָא מַלֵילִית עִמָךְ לְמֵימַר כֹּל דִי יְמַלֵל יְיָ יָתֵיהּ אַעֲבֵיד:
@67 וַאֲמַר בָּלָק לְבִלְעָם אִיתָא כְּעַן אֲדַבְּרִינָךְ לַאֲתַר אָחֳרָן מָאִים יְהֵי רַעֲוָא מִן קֳדָם יְיָ וּתְלוּטֵיהּ לִי מִתַּמָן:
@68 וּדְבַר בָּלָק יַת בִּלְעָם רֵישׁ רָמָתָא דְמִסְתַּכְּיָא עַל אַפֵּי בֵּית יְשִׁימוֹן:
@69 וַאֲמַר בִּלְעָם לְבָלָק בְּנֵה לִי הָכָא שַׁבְעָא מַדְבְּחִין וְאַתְקִין לִי הָכָא שַׁבְעָא תוֹרִין וְשַׁבְעָא דִכְרִין:
@70 וַעֲבַד בָּלָק כְּמָא דִי אֲמַר בִּלְעָם וְאַסֵיק תּוֹר וּדְכַר עַל כָּל מַדְבְּחָא:
@71 וַחֲזָא בִלְעָם אֲרֵי תַקִין קֳדָם יְיָ לְבָרָכָא יַת יִשְׂרָאֵל וְלָא הַלַךְ כִּזְמַן בִּזְמַן אֱלָהֵין לָקֳדָמוּת נְחָשַׁיָא וְשַׁוִי לָקָבֵיל עֶגְלָא דַעֲבָדוּ יִשְׂרָאֵל בְּמַדְבְּרָא אַפּוֹהִי:
@72 וּזְקֵף בִּלְעָם יָת עֵינוֹהִי וַחֲזָא יָת יִשְׂרָאֵל שָׁרָן לְשִׁבְטוֹהִי וּשְׁרַת עֲלוֹהִי רוּחַ נְבוּאָה מִן קֳדָם יְיָ:
@73 וּנְטַל מַתְלֵיהּ וַאֲמַר אֵימַר בִּלְעָם בְּרֵיהּ בְעוֹר וְאֵימַר גַבְרָא דְשַׁפִּיר חָזֵי:
@74 אֵימַר דִשְׁמַע מֵימַר מִן קֳדָם אֵל וְחֵזוּ מִן קֳדָם שַׁדַי חָזֵי שְׁכִיב וּמִתְגְלֵי לֵיהּ:
@75 מָה טָבָא מַשְׁכְּנָךְ יַעֲקֹב בֵּית מֵישְׁרָךְ יִשְׂרָאֵל:
@76 כְּנַחֲלִין דִמְדַבְּרִין כְּגִינַת שַׁקְיָא דְעַל פְּרָת כְּבוּסְמַיָא דִנְצִיב יְיָ כְּאַרְזִין דִנְצִבִין עַל מַיָא:
@77 יִסְגֵי מַלְכָּא דְיִתְרַבָּא מִבְּנוֹהִי וְיִשְׁלוֹט בְּעַמְמִין סַגִיאִין וְיִתְקוֹף מֵאֲגַג מַלְכֵּיהּ וְתִתְנַטֵל מַלְכוּתֵיהּ:
@78 אֱלָהָא דְאַפֵּקִינוּן מִמִצְרַיִם תּוּקְפָא וְרוּמָא דִילֵיהּ יֵיכְלוּן בְּנֵי יִשְׂרָאֵל נִכְסֵי עַמְמַיָא סַנְאֵיהוֹן וּבְבִזַת מַלְכֵּיהוֹן יִתְפַּנְקוּן וְאַרְעֲתְהוֹן יַחְסְנוּן:
@79 יְנוּחַ יִשְׁרֵי בִתְקוֹף כְּאַרְיָא וּכְלֵתָא לֵית מַלְכוּ דְתִזַעֲזְעִינֵיהּ בְּרִיכָךְ יְהוֹן בְּרִיכִין וְלִיטָךְ יְהוֹן לִיטִין:
@80 וּתְקֵיף רוּגְזָא דְבָלָק בְּבִלְעָם וּשְׁקָפִינוּן לִידוֹהִי וַאֲמַר בָּלָק לְבִלְעָם לְמֵילַט סַנְאַי קְרִיתָךְ וְהָא בָּרָכָא מְבָרְכַת לְהוֹן דְנַן תְּלַת זִמְנִין:
@81 וּכְעַן אִזֵיל לָךְ לְאַתְרָךְ אֲמָרִית יְקָרָא אֲיַקְרִינָךְ וְהָא מְנָעָךְ יְיָ מִן יְקָר:
@82 וַאֲמַר בִּלְעָם לְבָלָּק הֲלָא אַף לְאִזְגַדָךְ דִי שַׁלְחַת לְוָתִי מַלֵילִית לְמֵימָר:
@83 אִם יִתֶּן לִי בָלָק מְלֵי בֵיתֵיהּ כְּסַף וּדְהַב לֵית לִי רְשׁוּ לְמֶעֱבַּר עַל גְזֵירַת מֵימְרָא דַיְיָ לְמֶעֱבַּד טַבְתָּא אוֹ בִּישְׁתָּא מֵרְעוּתִי דִי יְמַלֵל יְיָ יָתֵיהּ אֲמַלֵיל:
@84 וּכְעַן הָא אֲנָא אָזֵיל לְעַמִי אִיתָא אֲמַלְכִינָךְ מָה דְתַּעְבֵיד וַאֲחַוֵי לָךְ מָא דְיַעֲבֵד עַמָא הָדֵין לְעַמָךְ בְּסוֹף יוֹמַיָא:
@85 וּנְטַל מַתְלֵיהּ וַאֲמַר אֵימַר בִּלְעָם בְּרֵיהּ בְעוֹר וְאֵימַר גַבְרָא דְשַׁפִּיר חָזֵי:
@86 אֵימַר דִשְׁמַע מֵימַר מִן קֳדָם אֵל וִידַע מַדַע מִן קֳדָם עִילָאָה חֵיזוּ מִן קֳדָם שַׁדַי חָזֵי שְׁכִיב וּמִתְגְלֵי לֵיהּ:
@87 חֲזִיתֵיהּ וְלָא כְעַן סְכִיתֵיהּ וְלָא אִיתוֹהִי קָרִיב כַּד יְקוּם מַלְכָּא מִיַעֲקֹב וְיִתְרַבָּא מְשִׁיחָא מִיִשְׂרָאֵל וְיִקְטּוֹל רַבְרְבֵי מוֹאָב וְיִשְׁלוֹט בְּכָל בְּנֵי אֱנָשָׁא:
@88 וִיהֵי אֱדוֹם יְרוּתָּא וִיהֵי יְרוּתָּא שֵׂעִיר לְבַעֲלֵי דְבָבוֹהִי וְיִשְׂרָאֵל יַצְלַח בְּנִכְסִין:
@89 וְיֵיחוּת חָד מִדְבֵית יַעֲקֹב וְיוֹבִיד מְשֵׁיזִיב מִקִרְיַת עַמְמַיָא:
@90 וַחֲזָא יַת עֲמַלְקָאָה וּנְטַל מַתְלֵיהּ וַאַמַר רֵישׁ קְרָבַיָא דְיִשְׂרָאֵל הֲוָה עֲמַלְקָאָה וְסוֹפֵיהּ לְעָלְמָא יֵיבָד:
@91 וַחֲזָא יַת שַׁלְמָאָה וּנְטַל מַתְלֵיהּ וַאֲמַר תַּקִיף בֵּית מוֹתְבָךְ וְשַׁוֵי בִכְרַךְ תַּקִּיף מְדוֹרָךְ:
@92 אֲרֵי אִם יְהֵי לְשֵׁיצָאָה שַׁלְמָאָה עַד מָה אֲתוּרָאָה יִשְׁבִּינָךְ:
@93 וּנְטַל מַתְלֵיהּ וַאֲמַר וַי לְחַיָיבַיָא דְיֵחוֹן כַּד יַעֲבֵּד אֱלָהָא יָת אִלֵין:
@94 וְסִיעַן יִצְטַרְחַן מֵרוֹמָאֵי וִיעֲנוּן לְאָתוּר וְיִשְׁתַּעְבְּדוּן לְעֵבַר פְּרָת וְאַף אִינוּן לְעָלְמָא יֵיבְדוּן:
@95 וְקָם בִּלְעָם וַאֲזַל וְתָב לְאַתְרֵיהּ וְאַף בָּלָק אֲזַל לְאוֹרְחֵיהּ:
@96 וִיתֵיב יִשְׂרָאֵל בְּשִׁיטִין וּשְׁרֵי עַמָא לְמִטְּעֵי בָּתַר בְּנַת מוֹאָב:
@97 וּקְרָאָן לְעַמָא לְדִבְחֵי טַעֲוַתְהוֹן וַאֲכַל עַמָא וּסְגִידוּ לְטַעֲוַתְהוֹן:
@98 וְאִתְחַבַּר יִשְׂרָאֵל לְבַעֲלָא פְעוֹר וּתְקֵף רוּגְזָא דַיְיָ בְּיִשְׂרָאֵל:
@99 וַאֲמַר יְיָ לְמשֶׁה דְבַר יַת כָּל רֵישֵׁי עַמָא וְדוּן וּקְטוֹל דְחַיָב קְטוֹל קֳדָם יְיָ לָקֳבֵל שִׁמְשָׁא וִיתוּב תְּקוֹף רוּגְזָא דַיְיָ מִיִשְׂרָאֵל:
@100 וַאֲמַר משֶׁה לְדַיָנֵי יִשְׂרָאֵל קְטִילוּ גְבַר גַבְרוֹהִי דְאִתְחַבָּרוּ לְבַעֲלָא פְעוֹר:
@101 וְהָא גַבְרָא מִבְּנֵי יִשְׂרָאֵל אֲתָא וְקָרֵב לְוָת אֲחוֹהִי יָת מִדְיָנֵיתָא לְעֵינֵי משֶׁה וּלְעֵינֵי כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל וְאִינוּן בָּכָן בִּתְרַע מַשְׁכַּן זִמְנָא:
@102 וַחֲזָא פִּינְחָס בַּר אֶלְעָזָר בַּר אַהֲרֹן כַּהֲנָא וְקָם מִגוֹ כְנִשְׁתָּא וּנְסֵיב רוֹמְחָא בִידֵיהּ:
@103 וְעַל בָּתַר גַבְרָא בַּר יִשְׂרָאֵל לְקוּבָּתָא וּבְזַע יַת תַּרְוֵיהוֹן יַת גַבְרָא בַּר יִשְׂרָאֵל וְיַת אִתְּתָא לִמְעָהָא וְאִתְכְּלִי מוֹתָנָא מֵעַל בְּנֵי יִשְׂרָאֵל:
@104 וַהֲווֹ דְמִיתוּ בְּמוֹתָנָא עַשְׂרִין וְאַרְבְּעָה אַלְפִין: פפפ:

@1 **וירא בלק בן צפור את כל אשר עשה ישראל לאמרי.** אמר אלו שני מלכים שהיינו בטוחים עליהם לא עמדו בפניהם, אנו על אחת כמה וכמה. לפיכך ויגר מואב:
@2 **ויגר.** לשון מורא, כמו (איוב יט, כט) גורו לכם: **ויקץ מואב.** קצו בחייהם:
@3 **אל זקני מדין.** והלא מעולם היו שונאים זה את זה, שנאמר (בראשית לו, לה) המכה את מדין בשדה מואב, שבאו מדין על מואב למלחמה. אלא מיראתן של ישראל עשו שלום ביניהם. ומה ראה מואב לטול עצה ממדין, כיון שראו את ישראל נוצחים שלא כמנהג העולם, אמרו מנהיגם של אלו במדין נתגדל, נשאל מהם מה מדתו. אמרו לו אין כחו אלא בפיו. אמרו אף אנו נבא עליהם באדם שכחו בפיו: **כלחוך השור.** כל מה שהשור מלחך אין בו ברכה: **בעת ההוא.** לא היה ראוי למלכות. מנסיכי מדין היה, וכיון שמת סיחון מנוהו עליהם לצורך שעה:
@4 **פתורה.** כשלחני הזה שהכל מריצין לו מעות, כך כל המלכים מריצין לו אגרותיהם. ולפי פשוטו של מקרא כך שם המקום: **ארץ בני עמו.** של בלק. משם היה, וזה היה מתנבא ואומר לו עתיד אתה למלוך. ואם תאמר מפני מה השרה הקדוש ברוך הוא שכינתו על גוי רשע, כדי שלא יהא פתחון פה לאמות לומר אלו היו לנו נביאים חזרנו למוטב, העמיד להם נביאים והם פרצו גדר העולם, שבתחלה היו גדורים בעריות וזה נתן להם עצה להפקיר עצמן לזנות: **לקרא לו.** הקריאה שלו היתה ולהנאתו, שהיה פוסק לו ממון הרבה: **עם יצא ממצרים.** ואם תאמר מה מזיקך: **הנה כסה את עין הארץ.** סיחון ועוג שהיו שומרים אותנו עמדו עליהם והרגום: **והוא ישב ממלי.** חסר כתיב, קרובים הם להכריתני, כמו (תהלים קיח, י) כי אמילם:
@5 **נכה בו.** אני ועמי נכה לו בהם. דבר אחר לשון משנה היא (ב''מ קה ב) מנכה לו מן הדמים, לחסר מהם מעט: **כי ידעתי** וגו' **.** על ידי מלחמת סיחון שעזרתו להכות את מואב:
@6 **וקסמים בידם.** כל מיני קסמים, שלא יאמר אין כלי תשמישי עמי. דבר אחר קסם זה נטלו בידם זקני מדין, אמרו אם יבא עמנו בפעם הזאת יש בו ממש, ואם ידחנו אין בו תועלת, לפיכך כשאמר להם לינו פה הלילה, אמרו אין בו תקוה, הניחוהו והלכו להם, שנאמר וישבו שרי מואב עם בלעם, אבל זקני מדין הלכו להם:
@7 **לינו פה הלילה.** אין רוח הקדש שורה עליו אלא בלילה, וכן לכל נביאי אמות העולם, וכן לבן בחלום הלילה, שנאמר (בראשית לא, כד) ויבא אלהים אל לבן הארמי בחלם הלילה. כאדם ההולך אצל פלגשו בהחבא: **כאשר ידבר ה' אלי.** אם ימליכני ללכת עם בני אדם כמותכם אלך עמכם, שמא אין כבודו לתתי להלך אלא עם שרים גדולים מכם: **וישבו.** לשון עכבה:
@8 **מי האנשים האלה עמך.** להטעותו בא. אמר פעמים שאין הכל גלוי לפניו, אין דעתו שוה עליו, אף אני אראה עת שאוכל לקלל ולא יבין:
@9 **בלק בן צפור** וגו' **.** אף על פי שאיני חשוב בעיניך, חשוב אני בעיני המלכים:
@10 **קבה לי.** זו קשה מארה לי, שהוא נוקב ומפרש: **וגרשתיו.** מן העולם. ובלק לא אמר אלא ואגרשנו מן הארץ, איני מבקש אלא להסיעם מעלי, ובלעם היה שונאם יותר מבלק:
@11 **לא תלך עמהם.** אמר לו אם כן אקללם במקומי. אמר לו לא תאר את העם. אמר לו אם כן אברכם. אמר לו אינם צריכין לברכתך, כי ברוך הוא. משל אומרים לצרעה לא מדבשיך ולא מעקציך:
@12 **להלך עמכם.** אלא עם שרים גדולים מכם. למדנו שרוחו גבוהה ולא רצה לגלות שהוא ברשותו של מקום אלא בלשון גסות, לפיכך ויוסף עוד בלק:
@16 **כי כבד אכבדך מאד.** יותר ממה שהיית נוטל לשעבר אני נותן לך:
@17 **מלא ביתו כסף וזהב.** למדנו שנפשו רחבה ומחמד ממון אחרים. אמר, ראוי לו לתן לי כל כסף וזהב שלו, שהרי צריך לשכור חילות רבות, ספק נוצח ספק אינו נוצח, ואני ודאי נוצח: **לא אוכל לעבר.** על כרחו גלה שהוא ברשות אחרים, ונתנבא כאן שאינו יכול לבטל הברכות שנתברכו האבות מפי השכינה:
@18 **גם אתם.** פיו הכשילו, גם אתם סופכם לילך בפחי נפש כראשונים: **מה יסף.** לא ישנה דבריו מברכה לקללה הלואי שלא יוסיף לברך, כאן נתנבא שעתיד להוסיף להם ברכות על ידו:
@19 **אם לקרא לך.** אם הקריאה שלך וסבור אתה לטול עליה שכר, קום לך אתם: **ואך.** על כרחך את הדבר אשר אדבר אליך אתו תעשה, ואף על פי כן וילך בלעם, אמר שמא אפתנו ויתרצה:
@20 **ויחבש את אתנו.** מכאן שהשנאה מקלקלת את השורה, שחבש הוא בעצמו. אמר הקדוש ברוך הוא רשע כבר קדמך אברהם אביהם, שנאמר (בראשית כב, ג) וישכם אברהם בבקר ויחבש את חמורו: **עם שרי מואב.** לבו כלבם שוה:
@21 **כי הולך הוא.** ראה שהדבר רע בעיני המקום ונתאוה לילך: **לשטן לו.** מלאך של רחמים היה והיה רוצה למנעו מלחטוא, שלא יחטא ויאבד: **ושני נעריו עמו.** מכאן לאדם חשוב היוצא לדרך יוליך עמו שני אנשים לשמשו וחוזרים ומשמשים זה את זה:
@22 **ותרא האתון.** והוא לא ראה, שנתן הקדוש ברוך הוא רשות לבהמה לראות יותר מן האדם, שמתוך שיש בו דעת תטרף דעתו כשיראה מזיקין: **וחרבו שלופה בידו.** אמר רשע זה הניח כלי אמנותו, שכלי זינן של אמות העולם בחרב, והוא בא עליהם בפיו, שהוא אמנות שלהם, אף אני אתפוש את שלו ואבוא עליו באמנותו. וכן היה סופו (במדבר לא, ח) ואת בלעם בן בעור הרגו בחרב:
@23 **במשעול.** כתרגומו בשביל. וכן (מ''א כ, י) אם ישפק עפר שומרון לשעלים. עפר הנדבק בכפות הרגלים בהלוכן, וכן (ישעיה מ, יב) מי מדד בשעלו מים, ברגליו ובהלוכו: **גדר מזה וגדר מזה.** סתם גדר של אבנים הוא:
@24 **ותלחץ.** היא עצמה: **ותלחץ.** את אחרים, את רגל בלעם:
@25 **ויוסף מלאך ה' עבור.** לעבור עוד לפניו להלוך להיות לפניו במקום אחר, כמו (בראשית לג, ג) והוא עבר לפניהם. ומדרש אגדה יש בתנחומא מה ראה לעמוד בשלשה מקומות, סימני אבות הראהו:
@27 **זה שלש רגלים.** רמז לו אתה מבקש לעקור אמה החוגגת שלש רגלים בשנה:
@28 **התעללת.** כתרגומו לשון גנאי ובזיון: **לו יש חרב בידי.** גנות גדולה היה לו דבר זה בעיני השרים, זה הולך להרוג אמה שלמה בפיו, ולאתון זו צריך לכלי זין:
@29 **ההסכן הסכנתי.** כתרגומו, וכן (איוב כב, ב) הלאל יסכן גבר. ורבותינו דרשו מקרא זה בגמרא אמרו ליה, מאי טעמא לא רכבת אסוסיא. אמר להון ברטיבא שדאי ליה וכו' , כדאיתא במסכת עבודה זרה (ד, ב) :
@31 **כי ירט הדרך לנגדי.** רבותינו חכמי המשנה דרשוהו (שבת קה, א) נוטריקון יראה ראתה, נטתה, בשביל שהדרך לנגדי, כלומר לקנאתי ולהקניטני. ולפי משמעו כי חרד הדרך לנגדי לשון רטט, כי ראיתי בעל הדרך שחרד ומהר הדרך שהוא לכעסי ולהמרותי [ולהמראתי] . ומקרא קצר הוא, כמו (ש''ב יג, לט) ותכל דוד. לישנא אחרינא ירט לשון רצון, וכן (איוב טז) ועל ידי רשעים ירטני, מפייס ומנחם אותי על ידי רשעים, שאינן אלא מקניטים:
@32 **אולי נטתה.** כמו לולא, פעמים שאולי משמש בלשון לולא: **גם אתכה הרגתי.** הרי זה מקרא מסורס, והוא כמו גם הרגתי אותך, כלומר לא העכבה בלבד קראתך על ידי, כי גם ההריגה: **ואותה החייתי.** ועתה מפני שדברה והוכיחתך ולא יכלת לעמוד בתוכחתה, כמו שכתוב (פסוק ל) ויאמר לא. על כן הרגתיה, שלא יאמרו זו היא שסלקה את בלעם בתוכחתה ולא יכול להשיב, שחס המקום על כבוד הבריות, וכן (ויקרא כ, טו. טז) ואת הבהמה תהרגו, וכן (שם) והרגת את האשה ואת הבהמה:
@33 **כי לא ידעתי.** גם זה גנותו, ועל כרחו הודה, שהוא היה משתבח שיודע דעת עליון, ופיו העיד לא ידעתי: **אם רע בעיניך אשובה לי.** להתריס נגד המקום היא תשובה זו. אמר לו הוא בעצמו צוני ללכת, ואתה מלאך מבטל את דבריו, למוד הוא בכך, שאמר דבר ומלאך מחזירו, אמר לאברהם (בראשית כב, ב) קח נא את בנך וגו' , ועל ידי מלאך בטל את דברו, אף אני אם רע בעיניך צריך אני לשוב:
@34 **לך עם האנשים.** בדרך שאדם רוצה לילך בה, מוליכין אותו. **לך עם האנשים.** כי חלקך עמהם וסופך להאבד מן העולם: **ואפס.** על כרחך את הדבר אשר אדבר וגו' : **עם שרי בלק.** שמח לקללם כמותם:
@35 **וישמע בלק.** שלח שלוחים לבשרו: **אל עיר מואב.** אל מטרופולין שלו, עיר החשובה שלו, לומר ראה מה אלו מבקשים לעקור:
@36 **האמנם לא אוכל כבדך.** נתנבא שסופו לצאת מעמו בקלון:
@38 **קרית חצות.** עיר מלאה שוקים אנשים ונשים וטף בחוצותיה, לומר ראה ורחם שלא יעקרו אלו:
@39 **בקר וצאן.** דבר מועט, בקר אחד וצאן אחד בלבד:
@40 **במות בעל.** כתרגומו לרמת דחלתיה, שם עבודה זרה:
@43 **אולי יקרה ה' לקראתי.** אינו רגיל לדבר עמי ביום: **וילך שפי.** כתרגומו יחידי, לשון שופי ושקט, שאין עמו אלא שתיקה:
@44 **ויקר.** לשון עראי, לשון גנאי, לשון טמאת קרי, כלומר בקושי ובבזיון, ולא היה נגלה עליו ביום אלא בשביל להראות חבתן של ישראל: **את שבעת המזבחת.** שבעה מזבחות ערכתי אין כתיב כאן, אלא את שבעת המזבחות, אמר לפניו אבותיהם של אלו בנו לפניך שבעה מזבחות, ואני ערכתי כנגד כלן. אברהם בנה ארבעה (בראשית יב, ז) ויבן שם מזבח לה' הנראה אליו, (שם יב, ח) ויעתק משם ההרה וגו' , (שם יג, יח) ויאהל אברם וגו' ואחד בהר המוריה. ויצחק בנה אחד (שם כו, כה) ויבן שם מזבח וגו' . ויעקב בנה שתים, אחד בשכם ואחד בבית אל: **ואעל פר ואיל במזבח.** ואברהם לא העלה אלא איל אחד:
@47 **ארה לי יעקב ולכה זעמה ישראל.** בשני שמותיהם אמר לו לקללם, שמא אחד מהם אינו מבהק:
@48 **מה אקב לא קבה אל.** כשהיו ראוים להתקלל לא נתקללו, כשהזכיר אביהם את עונם, כי באפם הרגו איש. לא קלל אלא אפם, שנאמר (בראשית מט) ארור אפם. כשנכנס אביהם במרמה אצל אביו היה ראוי להתקלל, מה נאמר שם (שם כז, לג) גם ברוך יהיה. במברכים נאמר (דברים כז, יב) אלה יעמדו לברך את העם. במקללים לא נאמר ואלה יעמדו לקלל את העם, אלא על הקללה, לא רצה להזכיר עליהם שם קללה: **לא זעם ה'.** אני אין כחי אלא שאני יודע לכון השעה שהקדוש ברוך הוא כועס בה, והוא לא כעס כל הימים הללו שבאתי אליך, וזהו שנאמר (מיכה ו, ה) עמי זכר נא מה יעץ וגו' ומה ענה אתו בלעם וגו' למען דעת צדקות ה':
@49 **כי מראש צרים אראנו.** אני מסתכל בראשיתם ובתחלת שרשיהם, ואני רואה אותם מיסדים וחזקים כצורים וגבעות הללו על ידי אבות ואמהות: **הן עם לבדד ישכן.** הוא אשר זכו לו אבותיו לשכון בדד, כתרגומו: **ובגוים לא יתחשב.** כתרגומו, לא יהיו נעשין כלה עם שאר האמות, שנאמר (ירמיה ל, יא) כי אעשה כלה בכל הגוים וגו' אינן נמנין עם השאר. דבר אחר כשהן שמחין אין אמה שמחה עמהם, שנאמר (דברים לב, יב) ה' בדד ינחנו. וכשהאמות בטובה, הם אוכלין עם כל אחד ואחד ואין עולה להם מן החשבון, וזהו, ובגוים לא יתחשב:
@50 **מי מנה עפר יעקב** וגו' **.** כתרגומו, דעדקיא דבית יעקב וכו' מארבע משריתא, מארבע דגלים. דבר אחר עפר יעקב אין חשבון במצות שהם מקימין בעפר (דברים כב, י) לא תחרוש בשור ובחמור, (ויקרא יט, יט) לא תזרע כלאים, אפר פרה, ועפר סוטה וכיוצא בהם: **ומספר את רבע ישראל.** רביעותיהן, זרע היוצא מן התשמיש שלהם: **תמת נפשי מות ישרים.** שבהם:
@53 **וקבנו לי.** לשון צווי, קללהו לי:
@54 **שדה צופים.** מקום גבוה היה ששם הצופה עומד לשמור אם יבא חיל על העיר: **ראש הפסגה.** בלעם לא היה קוסם כבלק, ראה בלק שעתידה פרצה להפרץ בישראל משם ששם מת משה. כסבור ששם תחול עליהם הקללה, וזו היא הפרצה שאני רואה:
@55 **אקרה כה.** מאת הקדוש ברוך הוא: **אקרה.** לשון אתפעל:
@56 **וישם דבר בפיו.** ומה היא השימה הזאת, ומה חסר המקרא באמרו שוב אל בלק וכה תדבר, אלא כשהיה שומע שאינו נרשה לקלל, אמר מה אני חוזר אצל בלק לצערו. ונתן לו הקדוש ברוך הוא רסן וחכה בפיו כאדם הפוקס בהמה בחכה להוליכה אל אשר ירצה. אמר לו על כרחך תשוב אל בלק:
@57 **ושרי מואב אתו.** ולמעלה הוא אומר וכל שרי מואב, כיון שראו שאין בו תקוה הלכו להם מקצתם, ולא נשארו אלא מקצתם: **מה דבר ה'.** לשון צחוק הוא זה, כלומר אינך ברשותך:
@58 **קום בלק.** כיון שראהו מצחק בו, נתכון לצערו עמוד על רגליך, אינך רשאי לישב ואני שלוח אליך בשליחותו של מקום: **בנו צפר.** לשון מקרא הוא זה, כמו (תהלים קד, כ) חיתו יער, (בראשית א, כד) וחיתו ארץ, (תהלים קיד, ח) למעינו מים:
@59 **לא איש אל** וגו' **.** כבר נשבע להם להביאם ולהורישם ארץ שבעה אמות, ואתה סבור להמיתם במדבר: **ההוא אמר** וגו' **.** בלשון תמה, ותרגומו תיבין ומתמלכין, חוזרים ונמלכין לחזור בהם:
@60 **הנה ברך לקחתי.** אתה שואלני מה דבר ה', קבלתי ממנו לברך אותם: **וברך ולא אשיבנה.** הוא ברך אותם ואני לא אשיב את ברכתו: **וברך.** כמו וברך וכן הוא גזרת רי''ש, כמו (תהלים עד, יח) אויב חרף, כמו חרף, וכן (שם י, ג) ובוצע ברך, המהלל ומברך את הגוזל ואומר, אל תירא כי לא תענש, שלום יהיה לך, מרגיז הוא להקדוש ברוך הוא. ואין לומר ברך שם דבר, שאם כן היה נקוד בפתח קטן וטעמו למעלה, אבל לפי שהוא לשון פעל הוא נקוד קמץ, וטעמו למטה:
@61 **לא הביט און ביעקב** וגו' **.** כתרגומו. דבר אחר אחרי פשוטו הוא נדרש מדרש נאה. **לא הביט.** הקדוש ברוך הוא און שביעקב, כשהן עוברין על דבריו אינו מדקדק אחריהם להתבונן באוניות [באון] שלהם ובעמלן שהן עוברין על דתו: **עמל.** לשון עברה, כמו והרה עמל (תהלים ז, טו) , כי אתה עמל וכעס תביט (שם י, יד) לפי שהעברה היא עמל לפני המקום: **ה' אלהיו עמו.** אפלו מכעיסין וממרים לפניו אינו זז מתוכן: **ותרועת מלך בו.** לשון חבה ורעות כמו רעה דוד (שמואל ב' טו, לז) אוהב דוד, ויתנה למרעהו (שופטים טו, ו) וכן תרגם אנקלוס ושכינת מלכהון ביניהון:
@62 **אל מוציאם ממצרים.** אתה אמרת הנה עם יצא ממצרים, לא יצא מעצמו אלא האלהים הוציאם: **כתועפות ראם לו.** כתוקף רום וגובה שלו, וכן וכסף תועפות (איוב כב כה) , לשון מעוז המה, ואומר אני שהוא לשון ועוף יעופף (בראשית א כ) , המעופף ברום וגובה ותקף רב הוא זה ותועפות ראם עפיפת גובה. דבר אחר, **תועפות ראם.** תקף ראמים, ואמרו רבותינו אלו השדים:
@63 **כי לא נחש ביעקב.** כי ראוים הם לברכה שאין בהם מנחשים וקוסמים: **כעת יאמר ליעקב** וגו' **.** עוד עתיד להיות עת כעת הזאת אשר תגלה חבתן לעין כל שהן יושבין לפניו ולומדים תורה מפיו ומחצתן לפנים ממלאכי השרת, והם ישאלו להם מה פעל אל, וזהו שנאמר והיו עיניך רואות את מוריך (ישעיה ל, כ) . דבר אחר יאמר ליעקב אינו לשון עתיד, אלא לשון הוה, אינן צריכין למנחש וקוסם כי בכל עת שצריך להאמר ליעקב ולישראל מה פעל הקדוש ברוך הוא ומה גזרותיו במרום, אינן מנחשים וקוסמים אלא נאמר להם על פי נביאיהם מה היא גזרת המקום, או אורים ותמים מגידים להם, ואונקלוס לא תרגם כן:
@64 **הן עם כלביא יקום** וגו' **.** כשהן עומדים משנתם שחרית, הן מתגברין כלביא וכארי לחטוף את המצות, ללבוש טלית לקרא את שמע ולהניח תפלין: **לא ישכב.** בלילה על מטתו עד שהוא אוכל ומחבל כל מזיק הבא לטרפו. כיצד, קורא את שמע על מטתו ומפקיד רוחו ביד המקום, בא מחנה וגיס להזיקם, הקדוש ברוך הוא שומרם ונלחם מלחמותם ומפילם חללים. דבר אחר הן עם כלביא יקום וגו' . כתרגומו: **ודם חללים ישתה.** נתנבא שאין משה מת עד שיפיל מלכי מדין חללים ויהרג הוא עמהם, שנאמר (יהושע יג, כב) ואת בלעם בן בעור הקוסם הרגו בני ישראל בחרב אל חלליהם:
@65 **גם קב לא תקבנו.** גם ראשון מוסיף על גם השני, וגם השני על גם ראשון, וכן גם לי גם לך לא יהיה (מלכים א' ג, כו) , וכן גם בחור גם בתולה (דברים לב, כה) :
@67 **וקבותו לי.** אין זה לשון צווי, כמו וקבנו, אלא לשון עתיד, אולי יישר בעיניו ותקבנו לי משם, מלדי''רש מי''י בלע''ז [תקלל אותו] :
@68 **ראש הפעור.** קוסם היה בלק וראה שהן עתידין ללקות על ידי פעור ולא היה יודע במה, אמר שמא הקללה תחול עליהם משם, וכן כל החוזים בכוכבים רואים ואינם יודעים מה רואים:
@71 **וירא בלעם כי טוב** וגו' **.** אמר איני צריך לבדוק בהקדוש ברוך הוא כי לא יחפוץ לקללם: **ולא הלך כפעם בפעם.** כאשר עשה שתי פעמים: **לקראת נחשים.** לנחש אולי יקרה ה' לקראתו כרצונו, אמר רוצה ואינו רוצה לקללם, אזכיר עונותיהם, והקללה על הזכרת העברה תחול: **וישת אל המדבר פניו.** כתרגומו:
@72 **וישא בלעם את עיניו.** בקש להכניס בהם עין רעה, והרי יש לך שלש מדותיו עין רעה ורוח גבוהה ונפש רחבה האמורים למעלה: **שוכן לשבטיו.** ראה כל שבט ושבט שוכן לעצמו ואינן מעורבין, ראה שאין פתחיהם מכונין זה כנגד זה, שלא יציץ לתוך אהל חברו: **ותהי עליו רוח אלהים.** עלה בלבו שלא יקללם:
@73 **בנו בער.** כמו למעינו מים (תהלים קיד, ח) . ומדרש אגדה שניהם היו גדולים מאבותיהם, בלק בנו צפור, אביו בנו הוא במלכות, ובלעם גדול מאביו בנביאות, מנה בן פרס היה: **שתם העין.** עינו נקורה ומוצאת לחוץ וחור שלה נראה פתוח, ולשון משנה הוא כדי שישתום ויסתום ויגוב (ע''ז סט.) ורבותינו אמרו לפי שאמר ומספר את רבע ישראל, שהקדוש ברוך הוא יושב ומונה רביעיותיהן של ישראל מתי תבא טפה שנלד הצדיק ממנה, אמר בלבו מי שהוא קדוש ומשרתיו קדושים יסתכל בדברים הללו, ועל דבר זה נסמת עינו של בלעם. ויש מפרשים שתום העין פתוח העין, כמו שתרגם אנקלוס, ועל שאמר שתום העין, ולא אמר שתום העינים, למדנו שסומא באחת מעיניו היה:
@74 **נפל וגלוי עינים.** פשוטו כתרגומו, שאין נראה עליו אלא בלילה כשהוא שוכב. ומדרשו כשהיה נגלה עליו לא היה בו כח לעמוד על רגליו ונופל על פניו, לפי שהיה ערל ומאוס להיות נגלה עליו בקומה זקופה לפניו:
@75 **מה טבו אהליך.** על שראה פתחיהם שאינן מכונין זה מול זה: **משכנתיך.** חניותיך, כתרגומו. דבר אחר מה טבו אהליך. מה טבו אהל שילה ובית עולמים בישובן שמקריבין בהן קרבנות לכפר עליהם: **משכנתיך.** אף כשהן חרבין, לפי שהן משכון עליכם, וחרבנן כפרה על הנפשות, שנאמר כלה ה' את חמתו (איכה ד) , ובמה כלה, ויצת אש בציון:
@76 **כנחלים נטיו.** שנארכו ונמשכו לנטות למרחוק, אמרו רבותינו מברכותיו של אותו רשע אנו למדים מה היה בלבו לקללם כשאמר (פסוק א) וישת אל המדבר פניו, וכשהפך המקום את פיו ברכם מעין אותן קללות שבקש לומר כו', כדאיתא בחלק (סנהדרין קה, א) : **כאהלים.** כתרגומו, לשון מור ואהלות (תהלים מה, ט) : **נטע ה'.** בגן עדן. לשון אחר כאהלים נטע ה', כשמים המתוחין כאהל: **נטע ה'.** לשון נטיעה מצינו באהלים, שנאמר ויטע אהלי אפדנו (דניאל יא, מה) :
@77 **מדליו.** מבארותיו. ופירושו כתרגומו: **וזרעו במים רבים.** לשון הצלחה הוא זה, כזרע הזרוע על פני המים: **וירם מאגג מלכו.** מלך ראשון שלהם יכבוש את אגג מלך עמלק: **ותנשא מלכותו.** של יעקב יותר ויותר, שיבא אחריו דוד ושלמה:
@78 **אל מוציאו ממצרים.** מי גורם להם הגדלה הזאת, אל המוציאם ממצרים, בתוקף ורום שלו יאכל את הגוים שהם צריו: **ועצמותיהם.** של צרים: **יגרם.** מנחם פתר בו לשון שבירה, וכן (צפניה ג, ג) לא גרמו לבקר, וכן (יחזקאל כג, לד) את חרשיה תגרמי, ואני אומר לשון עצם הוא שמגרר הבשר בשניו מסביב והמוח שבפנים, ומעמיד העצם על ערמימותה: **וחציו ימחץ.** אנקלוס תרגם חציו של צרים, חלוקה שלהם כמו (בראשית מט, כג) בעלי חצים, מרי פלוגתא, וכן ימחץ, לשון (שופטים ה, כו) ומחצה וחלפה רקתו, שיחצו את ארצם. ויש לפתור לשון חצים ממש, חציו של הקדוש ברוך הוא ימחץ בדמם של צרים, יטבול ויצטבע בדמם, כמו (תהלים סח, כד) למען תמחץ רגלך בדם. ואינו זז מלשון מכה, כמו מחצתי, שהצבוע בדם נראה כאלו מחוץ ונגוע:
@79 **כרע שכב כארי.** כתרגומו, יתישבו בארצם בכח וגבורה:
@80 **ויספק.** הכה זו על זו:
@83 **לעבר את פי ה'.** כאן לא נאמר אלהי, כמו שנאמר בראשונה, לפי שידע שנבאש בהקדוש ברוך הוא ונטרד:
@84 **הולך לעמי.** מעתה הריני כשאר עמי, שנסתלק הקדוש ברוך הוא מעליו: **לכה איעצך.** מה לך לעשות. ומה היא העצה, אלהיהם של אלו שונא זמה הוא כו' , כדאיתא בחלק (סנהדרין קו.) תדע שבלעם השיא עצה זו להכשילם בזמה, שהרי נאמר הן הנה היו לבני ישראל בדבר בלעם (לקמן לא, טז) : **אשר יעשה העם הזה לעמך.** מקרא קצר הוא זה, איעצך להכשילם, ואומר לך מה שהן עתידין להרע למואב באחרית הימים:
@86 **וידע דעת עליון.** לכון השעה שכועס בה:
@87 **אראנו.** רואה אני שבחו של יעקב וגדלתן, אך לא עתה היא, אלא לאחר זמן: **דרך כוכב.** כתרגומו, לשון דרך קשתו (איכה ב, ד) , שהכוכב עובר כחץ, ובלע''ז דישטנ''ט [מזנק] כלומר יקום מזל: **וקם שבט.** מלך רודה ומושל: **ומחץ פאתי מואב.** זה דוד, שנאמר בו השכב אותם ארצה וימדד שני חבלים להמית וגו' (שמואל ב' ח, ב) : **וקרקר.** לשון קורה כמו אני קרתי (מלכים ב' יט, כד) מקבת בור נקרתם (ישעיה נא, א) יקרוה עורבי נחל (משלי ל, יז) פורי''יר בלע''ז [לנקב] : **כל בני שת.** כל האמות, שכלם יצאו מן שת בנו של אדם הראשון:
@88 **והיה ירשה שעיר איביו.** ישראל:
@89 **וירד מיעקב.** ועוד יהיה מושל אחר מיעקב: **והאביד שריד מעיר.** מעיר החשובה של אדום והיא רומי, ועל מלך המשיח אומר כן, שנאמר בו וירד מים עד ים (תה' עב) ולא יהיה שריד לבית עשו (עוב' א) :
@90 **וירא את עמלק.** נסתכל בפרענותו של עמלק: **ראשית גוים עמלק.** הוא קדם את כלם להלחם בישראל, וכך תרגם אנקלוס ואחריתו לאבד בידם, שנאמר תמחה את זכר עמלק (דברים כה, יט) :
@91 **וירא את הקיני.** לפי שהיה קיני תקוע אצל עמלק, כענין שנאמר ויאמר שאול אל הקיני וגו' (שמואל א' טו, ו) הזכירו אחר עמלק, נסתכל בגדלתן של בני יתרו שנאמר בהם תרעתים שמעתים שוכתים (דברי הימים א' ב, נה) : **איתן מושבך.** תמה אני מהיכן זכית לכך הלא אתה עמי היית בעצת הבה נתחכמה לו (שמות א, י) , ועתה נתישבת באיתן ומעוז של ישראל:
@92 **כי אם יהיה לבער קין** וגו' **.** אשרך שנתקעת לתוקף זה שאינך נטרד עוד מן העולם, כי אף אם אתה עתיד לגלות עם עשרת השבטים ותהיה לבער ממקום שנתישבת שם, מה בכך: **עד מה אשור תשבך.** עד היכן הוא מגלה אותך, שמא ללחלח וחבור, אין זה טרוד מן העולם, אלא טלטול ממקום למקום ותשוב עם שאר הגליות:
@93 **וישא משלו** וגו' **.** כיון שהזכיר את שבית אשור אמר, **אוי מי יחיה משמו אל.** מי יכול להחיות את עצמו משמו את אלה שלא ישים עליו הגוזר את אלה, שיעמוד סנחריב ויבלבל את כל האמות, ועוד יבואו:
@94 **וצים מיד כתים.** ויעברו כתיים שהן רומיים בבירניות גדולות על אשור: **וענו עבר.** וענו אותם שבעבר הנהר: **וגם הוא עדי אבד.** וכן פרש דניאל עד די קטילת חיותא והובד גשמה (דניאל ז, יא) : **וצים.** ספינות גדולות, כדכתיב וצי אדיר (ישעיה לג, כא) תרגומו ובורני רבתא:
@96 **בשטים.** כך שמה: **לזנות אל בנות מואב.** על ידי עצת בלעם כדאיתא בחלק:
@97 **וישתחוו לאלהיהן.** כשתקף יצרו עליו ואמר לה השמעי לי, והיא מוציאה לו דמות פעור מחיקה ואומרת לו השתחוה לזה:
@98 **פעור.** על שם שפוערין לפניו פי הטבעת ומוציאין רעי, וזו היא עבודתו: **ויחר אף ה' בישראל.** שלח בהם מגפה:
@99 **קח את כל ראשי העם.** לשפוט את העובדים לפעור: **והוקע אותם.** את העובדים: **והוקע.** היא תליה, כמו שמצינו בבני שאול והוקענום לה' (שמואל ב' כא, ו) ושם תליה מפורשת בעבודה זרה בסקילה, וכל הנסקלין נתלין: **נגד השמש.** לעין כל. ומדרש אגדה השמש מודיע את החוטאים, הענן נקפל מכנגדו והחמה זורחת עליו:
@100 **הרגו איש אנשיו.** כל אחד ואחד מדיני ישראל היה הורג שנים, ודיני ישראל שמונת רבוא ושמונת אלפים, כדאיתא בסנהדרין (יח.) :
@101 **והנה איש מבני ישראל בא.** נתקבצו שבטו של שמעון אצל זמרי שהיה נשיא שלהם, אמרו לו אנו נדונין במיתה ואתה יושב וכו' , כדאיתא באלו הן הנשרפין (סנהדרין דף פב, א) : **את המדינית.** כזבי בת צור: **לעיני משה.** אמרו לו משה, זו אסורה או מתרת, אם תאמר אסורה, בת יתרו מי התירה לך וכו' , כדאיתא התם: **והמה בוכים.** נתעלמה ממנו הלכה כל הבועל ארמית קנאים פוגעים בו געו כלם בבכיה. בעגל עמד משה כנגד ששים רבוא, שנאמר (שמות לב, כ) ויטחן עד אשר דק וגו' וכאן רפו ידיו, אלא כדי שיבא פנחס ויטול את הראוי לו:
@102 **וירא פנחס.** ראה מעשה ונזכר הלכה, אמר לו למשה מקבלני ממך הבועל ארמית קנאין פוגעין בו, אמר לו קריינא דאגרתא איהו ליהוי פרוונקא, מיד ויקח רמח בידו וגו' :
@103 **אל הקבה.** אל האהל: **אל קבתה.** [אל הקבה] כמו הלחיים והקיבה כון בתוך זכרות של זמרי ונקבות שלה, וראו כלם שלא לחנם הרגם, והרבה נסים נעשו לו כו', כדאיתא התם (סנהד' פב:) :

@2 **ויגר מואב מפני העם** . בעבור כי רב הוא שהיה מואב קטן בגוים כי איננו עם קדמון כמו הכנעני והאמורי וזולתם מבני נח ויגורו מאד מפני העם שהיו רבים מאד מהם כי פרו וישרצו ויעצמו מהם ויקץ עוד מפני בני ישראל ששמעו המסות הגדולות הנעשות להם ולאבותיהם והנה ידעו מואב כי ישראל לא ילכדו את ארצם מהם כי שלחו להם כאשר שלחו לסיחון (דברים ב כט) עד אשר אעבור את הירדן אל הארץ אשר ה' אלהינו נותן לנו או ששמעו גם כן מניעת השם שאמר להם (שם שם ט) אל תצר את מואב ולכן אמרו לזקני מדין אפילו שלא ילכדו את ארצנו ילחכו ברובם את כל סביבותינו כלחוך השור את ירק השדה וילכדו להם את כל סביבותינו כאשר עשו לשני מלכי האמורי ויתנו אותנו למס עובד
@3 **זקני מדין** . אמר ר"א כי יתכן שהיו החמשה מלכים זקנים וא"כ וילכו זקני מואב וזקני מדין (בפסוק ז) אינם הזקנים הנזכרים תחלה כי המלכים לא הלכו לפניו רק שרים ככתוב (פסוק ח) ועל דעת רבותינו (במדב"ר כ ד) שאמרו מנהיגם של אלו במדין נתגדל ראוי להם לשלוח אל זקני מדין לא למלכים ולא לעם כי הזקנים הם היודעים ענינו והנראה בעיני כי היו מתחלה במדין מלכים וסיחון מלך האמורי נלחם במלך מואב הראשון ויקח את כל ארצו מידו עד ארנון ונלחם בבני עמון ולקח מארצם כמו שאמר מלך עמון ליפתח (שופטים יא יג) כי לקח ישראל את ארצי בעלותו ממצרים ויפתח השיב לו כי מסיחון לקחה (שם פסוק כא) וכתוב ביהושע (יג כה) ויהי להם הגבול יעזר וכל ערי הגלעד וחצי ארץ בני עמון עד ערוער ונלחם סיחון עוד עם מלכי מדין וכבש ארצם ושם אותם לו לעבדים נושאי מנחה והסיר עטרת ראשם ולא נתן להם הדר מלכות והשאירם שופטים בארץ מדין בעבורו ולכן יקראו " זקני מדין " כדרך השערה אל הזקנים (דברים כה ז) והראיה בזה שכתוב ביהושע (יג כא) וכל ממלכות סיחון מלך האמורי אשר מלך בחשבון אשר הכה משה אותו ואת נשיאי מדין את אוי ואת רקם ואת צור ואת חור ואת רבע נסיכי סיחון יושבי הארץ כי היתה תחת ממשלתו וטעם "ואת מלכי מדין" (להלן לא ח) אשר היו מלכים תחלה כמו שאמר "נשיאי מדין נסיכי סיחון" וכן נאמר (להלן כה טו) ראש אומות בית אב במדין הוא לא מלך או יהיה טעם "מלכי מדין" שחזרו למלכותם בעת ההיא ולא ידעתי טעם למה שאמר הכתוב ובלק בן צפור מלך למואב בעת ההיא כי הראוי הוא שיאמר תחלה וירא בלק בן צפור מלך מואב את כל אשר עשה ישראל לאמורי ואולי היה בלק גבור חיל נודע מאד במעשה תקפו וגבורתו והזכיר הכתוב כי אף על פי שהיה למואב בעת ההיא מלך תקיף ואמיץ לבו בגבורים היה ירא וקץ מאד מפני בני ישראל ולכך אמר יפתח (שופטים יא כה) הטוב טוב אתה מבלק בן צפור מלך מואב כי לא יפחיד את המלך רק במלך נורא מאד ויתכן כי מואב לא היה עליהם מלך והיה העם ירא מאד מפני בני ישראל ועשו שני דברים שלחו אל זקני מדין לאמר עתה ילחכו הקהל והקימו עליהם המלך הזה בעצת מדין ואחרי כן שלחו כלם אל בלעם במצות המלך וזה טעם "בעת ההיא" בהתיעצם בענין ישראל ושלחם לבלעם ויהיה טעם "וירא בלק" שהיה אחד משרי מואב וגבור חיל ונתעורר בענין הזה ואמר למואב הבה נתחכמה לעם והם קמו והמליכוהו בעצת מדין ובמדרש במדבר סיני רבה (כ ד) ראיתי ובלק בן צפור מלך למואב בעת ההיא והלא מתחלה נסיך היה שנאמר את אוי ואת רקם ואת צור ואת חור ואת רבע אלא משנהרג סיחון המליכוהו עליהם בעת ההיא שגרמה לו השעה
@4 **ארץ בני עמו** . של בלק משם היה וזה היה מתנבא ואומר לו עתיד אתה למלוך לשון רש"י מדברי אגדה (במדב"ר כ ז) ופשוטו ארץ בני עמו של בלעם כי שם נולד ושם יחוסו והטעם להזכיר כן מפני שהיה קוסם מן הארץ שכל עמה קוסמים כענין שכתוב (ישעיהו ב ו) כי מלאו מקדם ועוננים כפלשתים (ו) וטעם נכה בו אני ומדין עוזרי
@12 **אל שרי בלק** . על דעת רש"י (פסוק ז) כי זקני מדין הלכו להם כאשר אמר להם לינו פה הלילה ויתכן זה כי כאשר הזכיר להם כאשר ידבר ה' אלי (פסוק ח) לא רצו להמתין לו כי אמרו השם הזה בעזרתם של ישראל הוא מעולם הוא אשר הוציאם ממצרים ועשה להם אותות ומופתים כי זקני מדין חכמים היו וידעו כל דברי משה עם יתרו גדול ארצם אבל הכתוב לא הזכיר זה ור"א אמר כי לא הזכירם בעבור כי בלק הוא העיקר והוא בעל השליחות וכן וישבו שרי מואב (שם) כי עיקר השליחות מאדוניהם היה והנכון כי זקני מדין ואולי הם המלכים הראשונים באו מארצם אל בלק להתיעץ בענין ישראל ולקחו כלם עצה לשלוח לבלעם והנה שלח בלק השרים שלו שופטיו וחכמיו והלכו עם זקני מדין לארץ מדין כי משם היה דרכם אל עיר בלעם ונשארו זקני מדין בעירם והלכו שרי בלק שהם השלוחים לבדם עד ארם וזה טעם וילכו זקני מואב וזקני מדין כי הלכו מלפני בלק כולם עד מדין וקסמים בידם ויבאו אל בלעם שב לזקני מואב שבהם אמר וישלח מלאכים (פסוק ה) לא לזקני מדין
@12 "לתתי להלך עמכם" - אלא עם שרים גדולים למדנו שרוחו גסה ולא רצה לומר שהוא ברשותו של מקום אלא בלשון גסות ולפיכך ויסף עוד בלק שלח שרים לשון רש"י ואינו נכון כי כל כבודו שיתפאר ויתגדל בדבר השם ועוד שהוא לא היה חושב שיתן לו רשות ללכת עם שרים אחרים נכבדים אבל טעמו שאין השם חפץ שילך כלל והנה בלק חשד אותו כי להרבות שכרו אמר כן ולכך אמר לו (פסוק לז) למה לא הלכת אלי האמנם לא אוכל כבדך ועל כן הוסיף שלוח שרים רבים ונכבדים להראות לו כי הוא חפץ בו מאד ונדר לתת לו הון ועושר ככל אשר יצוה ויגזור עליו ובלעם השיב להם (פסוק יח) אם יתן לי בלק וגו' לא אוכל לעבור את פי ה' כי הוא אלהי ולא אוכל לעשות קטנה או גדולה אם אעבור את פיו כי בשמו אני עושה או יאמר לא אוכל לעבור את פיו בדבר קטן או גדול כי הוא אלהי ואני עבדו
@19 **אם לקרא לך באו האנשים** . אם הקריאה שלך וסבור אתה ליטול עליה שכר קום לך אתם ועל כרחך הדבר אשר אדבר אליך אתו תעשה ואף על פי כן וילך בלעם אמר שמא אפתנו ויתרצה לשון רש"י ויחר אף אלהים כי הולך הוא (פסוק כב) ראה שאין הדבר טוב בעיני המקום ונתאוה לילך גם זה לשון הרב ור"א כתב אמר הגאון אם יטעון טוען ויאמר אחר שאמר לו לא תלך עמהם (פסוק יב) איך אמר לו קום לך אתם יש להשיב כי השם לא רצה שילך עם הראשונים עד שיבאו שרים נכבדים מהם ולפי דעתי אין צורך כי טעמו כמו שלח לך אנשים (לעיל יג ב) כי השם אמר לישראל עלה רש (דברים א כא) והם לא האמינו רק אמרו (שם פסוק כב) נשלחה אנשים אז שאל משה את השם וכן זה כי מה צורך היה לו לומר (פסוק יט) ואדעה מה יוסף ה' דבר עמי רק חשב בלבו מחשבה רעה והשם אמר לו לך אתם רק השמר שלא תדבר רק מה שאומר לך והעד על פירושי ויחר אף אלהים כי הולך הוא אלו דבריו וכל זה איננו שוה לי כי מה שאמר הגאון איננו כן כי השם אמר לו (פסוק יב) לא תלך עמהם לא תאור את העם כי ברוך הוא בעבור שלא יקלל את העם ימנענו ואיך יהיה מותר לו ללכת עם שרים אחרים ולא מנעו מלכת בעבור חסרון מעלת השרים ומה שאמר ר"א איננו נכון שינחם האלהים וישיב דברו אחור בעבור עקשות השואל וענין שלח לך אנשים לא כן היה וכבר פירשתי טעמו (לעיל יג ב) ולא יעניש האלהים בדבר אשר יתן רשות בו וחלילה ובמדרש (במדב"ר כ יב) אמרו מכאן אתה למד שבדרך שאדם רוצה לילך בה מוליכין אותו והנכון בעיני בענין הזה כי מתחלה מנעו השם שלא יקלל את העם כי ברוך הוא ולמה ילך עמהם אחרי שלא יקללם והם לא יחפצו בו לדבר אחר על כן אמר לא תלך עמהם שלא תאור את העם כי ברוך הוא ובידוע כי בלעם הודיעם את דברי האלהים ובלק שלח אליו פעם שנית כי לא האמין והוסיף לו כבוד בשרים רבים ונכבדים מן הראשונים ונדר להרבות שכרו וכבודו ובלעם ענה אותם שאין הדבר תלוי בממון ולא ברצונו רק הכל ביד השם וישאל ממנו עוד מה יצוה אותו ועשה זה כהוגן כי מה ידע הוא בדעת עליון ועצת ה' לעולם טובה והוא יורה חטאים בדרך ויודיענו מה יענה מלאכי גוי או יגיד לו מה יקרה להם בעתיד והנה השם אמר לו כבר הודעתיך כי העם ברוך הוא ולא תוכל לקללם ועתה חזרו לפניך ואם לקרוא לך בלבד באו כלומר שיתרצו בלכתך עמהם על מנת שלא תקלל את העם כאשר הודעתיך מתחלה קום לך אתם ואך את הדבר אשר אדבר אליך אותו תעשה שאפילו אם אצוה אותך לברך שתברכם ו לא תירא מבלק וזה טעם " אם לקרא " וכן היה החפץ לשם הנכבד מתחלה שילך עמהם אחרי הודיעו אותם שלא יקללם ושיתנהג בענינם כאשר יצוה כי הרצון לפניו יתברך שיברך את ישראל מפי נביא לגוים והנה היה על בלעם להגיד כן לשרי בלק ולאמר הנה הרשה השם אותי להיות קרוא לכם בלבד אבל על מנת שלא לקלל את העם ועל מנת שאם יצוה אותי לברך שאברכם ואם לא יתרצו בכך יהיו מניחים אותו כי גם בפעם הזאת השנית אמר בלק (פסוק יז) ולכה נא קבה לי את העם הזה לא יחפוץ בו להודיעו עתידות ולא לדבר אחר זולתי לקוב את העם והנה בלעם מרוב חפצו ללכת לא הודיעם זה ולא אמר להם כלום ויקם בבקר ויחבוש את אתונו וילך עמהם כרוצה להשלים חפצם על כן חרה אף ה' כי הולך הוא שאלו הודיעם לא היה הולך ועוד שהיה בזה חלול ה' כי בלכתו עמהם סתם והוא ברשות השם חשבו שנתן לו רשות לקלל להם את העם והנה חזר בו ממה שאמר תחלה "לא תאור את העם כי ברוך הוא" כפי מה שהגיד להם וכאשר יראו עוד שלא יקללם יאמרו כי אחרי כן נמלך עוד או יהתל בהם כהתל באנוש חלילה לה' מעשות כדבר הזה כי נצח ישראל לא ינחם
@22 **ותרא האתון את מלאך ה'** . מלאכי השם השכלים הנבדלים לא יראו לחוש העינים כי אינם גוף נתפש במראה וכאשר יראו לנביאים או לאנשי הרוח הקודש כדניאל ישיגו אותם במראות הנפש המשכלת כאשר תגיע למעלת הנבואה או למדרגה שתחתיה אבל שיושגו לעיני הבהמה אי אפשר על כן תוכל לפרש "ותרא האתון" כי הרגישה בדבר מפחיד אותה מלעבור והוא המלאך אשר יצא לשטן כענין ולבי ראה הרבה חכמה ודעת (קהלת א טז) שיאמר על ההשגה לא על הראות וכאשר אירע בה הנס ושם לה הבורא הדבור אמרה לבלעם (פסוק ל) ההסכן הסכנתי לעשות לך כה אבל לא ידעה למה עשתה עתה כן כי לאונסה נעשה בה כך ולפיכך לא אמרה לו "הנה מלאך השם עומד לנגדי וחרבו שלופה בידו" כי לא עלתה השגתה לדעת זה כלל ואמר ותרא את מלאך ה' וחרבו שלופה בידו לא שתראה חרב אף כי מלאך אבל ירמוז הכתוב כי מפני היות המלאך נכון להכות בה חרדה חרדה גדולה נדמה לה כאלו באים לשחוט אותה ואם נאמר כי המלאכים הנראים בדמות אנשים כאשר הזכרתי בפרשת וירא (בראשית יח ב) יושגו אף לעיני הבהמות אם כן איך לא יראנו בלעם ולא הוכה בסנורים אבל יתכן שהוסיף בהשגת עיניה מי שהוסיף בה הדבור וראתה כאדם ולא הזכיר בה הכתוב "ויגל השם עיני האתון" כאשר הזכיר באדוניה (פסוק לא) כי הענין כולו באתון נס גדול כבריאה חדשה בנבראים בין השמשות ואינו נקרא גלוי עינים בלבד אבל רבותינו (אבות פ"ה מ"ו) לא יזכירו בנסים רק פתיחת פיה וטעם הנס הזה להראות לבלעם מי שם פה לאדם או מי ישום אלם להודיעו כי השם פותח פי הנאלמים וכל שכן שיאלם ברצונו פי המדברים גם ישים בפיהם דברים לדבר כרצונו כי הכל בידו ולהזהירו שלא ילך אחר נחש וקסם ויקללם בהם כי מנחש וקוסם היה
@30 **ויגל ה' את עיני בלעם** . מזה הכתוב נלמד כי בלעם לא היה נביא אלו היה נביא איך יצטרך לגלוי העינים בראיית המלאך כאשר יאמר הכתוב במי שלא הגיע לנבואה כנער אלישע (מלכים ב ו יז) והגר המצרית (בראשית כא יט) ולא יאמר כן בנביאים וכך קראו הכתוב (יהושע יג כב) בלעם בן בעור הקוסם ומה שאמר הוא (פסוק ח) כאשר ידבר ה' אלי יקרא ידיעתו העתידות בקסמיו "דבר ה'" אבל לכבוד ישראל בא אליו השם בלילה ההוא ואחרי כן זכה לגלוי עינים בראיית המלאך ודבר עמו ובסוף עלה למעלת מחזה שדי (להלן כד ד טז) והכל בעבור ישראל ולכבודם ואחרי ששב לארצו היה קוסם כי כן יקראנו הכתוב במיתתו (יהושע יג כב) ואת בלעם בן בעור הקוסם הרגו בחרב וחלילה שישלחו יד בנביא השם וכך אמרו במדרש במדבר סיני רבה (כ יט) בלעם נזקק לרוח הקדש וכשנזדווג לבלק נסתלקה ממנו רוח הקדש וחזר להיות קוסם כבתחלה לפיכך צווח רם הייתי והורידני בלק
@31 **כי ירט הדרך לנגדי** . כי ההולך ירט דרכו ועות אותה לנגד עיני כי אנכי היודע ועד או " לנגדי " שירט הדרך לעשות כנגד רצוני כדברי אונקלוס כמו כי הכעיסו לנגד הבונים (נחמיה ג לז) " ירט " לשון עוות וכן ועל ידי רשעים ירטני (איוב טז יא) יעות אותי והענין כאשר פירשתי (בפסוק כ) כי ההליכה היה בה רשות מאת ה' הנכבד אבל בלעם עות אותה בלכתו עמהם על דעתם שיקלל את העם
@32 **ותט לפני** . פירשו בו ותט אל השדה כאשר היתה לפני ואין צורך רק טעמו כמו מפני כי כן תשמש הלמ"ד כמו ויחדלו לבנות העיר (בראשית יא ח) חדל להשכיל להטיב (תהלים לו ד) וכן רבים וכמוהו ויצא יואב ושרי החיל לפני המלך לפקוד את העם את ישראל ( כד ד) וטעם אולי נטתה מפני על דעת המפרשים כמו לולא שנטתה מפני ישמש במקום הזה שלא כדרך חביריו כלם ועל דעתי הוא כמשמעו כי האתון הרגישה במלאך או ראתה בו ולא ידעה מה הענין אבל נטתה מפני חרב שלופה כמנהג הבהמות על כן אמר המלאך לבלעם ותראני האתון ונטתה מפני ובשמא נטתה מפני כי אני להרוג אותך באתי אבל אותה החייתי כי החטא בך ולא באתון
@32 "גם אתכה הרגתי" - אמר ר"א מלת "גם" לעד שמתה האתון אחרי שדברה וטעם החייתי כי בן אדם בראותו את המלאך ימות והעד ותנצל נפשי (בראשית לב לא) אף כי הבהמה שאין לה שום שותפות עם המלאך כבן אדם ואין מלת "גם" נדרש כאשר אמר כי שניהם לא ימותו כי עתה שנטתה מתה האתון והחיה את בלעם ואם לא נטתה היה הורג את בלעם ומחיה האתון אבל מלת "גם" כדברי רש"י שהוא כמסורס גם הרגתי אותך וטעם ואותה החייתי לומר כי החטא כולו עליך והרגתי אותך בו אבל היא אין עליה חטא שתמות בו והנה הנטיה שנטתה מפני לטובתך לא לצרכה כלל והכית אותה חנם וגמלת לה רעה תחת טובה ולא הגיד הכתוב אם היו שרי בלק עם בלעם במעשים האלה או שהיו רוכבים לפניו ורחוק היה ביניהם ובינו והקרוב שהיו עמו לא יתפרדו ממנו וראו בנטות האתון והכות בלעם אותה כסבורים היו שהיה כמנהג הבהמה הרעה ולא שמעו דבורה אף כי דבר המלאך שהוא גלוי עיני בלעם ורבותינו אמרו (במדב"ר כ יד) שהיו שרי מואב תמהים שראו נס שלא היה כמותו בעולם ואמרו (שם) שכיון שדברה מתה שלא יהו האומות אומרים זו היא שדברה ועושין אותה יראה ועוד שחס הקב"ה על כבודו של רשע שלא יהו אומרים זו היא שסלקה את בלעם וכל זה אפשר מדרך הקבלה לא שדבר הכתוב במיתתה כלל כאשר פירשתי
@34 **לך עם האנשים ואפס וגו'** . יתכן שיאמר לך עם האנשים ואפס את הדבר אשר אדבר אליך אותו תדבר ותודיע אותם זה או טעמו כי אחרי אשר התודה אם רע בעיניך אשובה לי (פסוק לד) אמר לו לך עמהם כי מחלתי על חטאתך ובלבד שתזכור אזהרתי אשר הזהרתיך והוצרך לומר לו כן שלא יחשוב שיאמר לו לך עמהם לעשות מה שבקשו ממך גם יתכן שהיה חפץ ההולך לקלל את העם ולא היה חפצו לברכם בשום פנים ולכן יזהירנו האלהים בכל עת שידבר עמו ומפני זה הודיע בלעם לבלק בתחלת דברו עמו (פסוק לח) הנה באתי אליך כי בביאה בלבד הורשיתי אבל בענין העם היכול אוכל דבר מאומה כרצונך הדבר אשר ישים אלהים בפי אותו אדבר בין קללה בין ברכה ראה אם תחפוץ שאדבר בענינם ואם לא תחפוץ בכך אשובה לי מעתה
@40 **ויעלהו במות בעל וירא משם קצה העם** . היה מעלה אותו במקום שיראנו כדי שיתכוין אליו בקללתו ולא תפרד נפשו מהם כי אלה מכחות הנפש להיות דבקה בעת הראיה כידוע מענין החכמים (ב"ק קיז) דלו לי גבינאי דבעינא למחזייה דלו ליה יהב ביה עיניה ונח נפשיה והגיד הכתוב כי לא ראה כל המחנה כי היו חונים ארבעה דגלים לארבע רוחות השמים ובפעם השנית אמר לו בלק (להלן כג יג) אפס קצהו תראה וכלו לא תראה לומר גם בפעם הזאת לא תראהו כלו אם הוא הדבר המונע ממך קללתו אבל קבנו לי משם אם תוכל כי אין לי מקום להראותו כלו משם חשב בלק אולי יש באחת הקצוות דגל אנשים צדיקים וטובים אשר אין השם חפץ דכאו ויתכן לפרש עוד כי בפעם הראשון ראהו כלו כי במות בעל מקום גבוה וראו שניהם משם קצה העם ובנו שם המזבחות והלך בלעם אל ראש הגבעה אשר בהר ההוא וראהו כולו וזה טעם "וילך שפי" (להלן כג ג) שהלך אל שפי שבו כדברי ר"א
@41 **שבעה מזבחות** . רמז בזה ר"א סוד עמוק והנה בלעם רצה לדבקה אליו הרצון מאת ה' בקרבנות האלה ולכן העלה עולות מספר כולם ורצה שיתעסק בלק עצמו בהם ולכך אמר ויעל בלק ובלעם פר ואיל במזבח זה שוחט וזה זורק וטעם ויאמר אליו את שבעת המזבחות ערכתי (פסוק ד) דרך תפלה כאומר ערכתי לפניך מזבח שלם בקרבן שלם יעלו על רצון מזבחך כענין שיאמר הכתוב (תהלים כ ד) יזכור כל מנחותיך ועולתך ידשנה סלה ויאמר (שם סו טו) עולות מחים אעלה לך עם קטרת אלים אעשה בקר עם עתודים סלה וכן במקומות רבים וטעם הידיעה כבר זכרה ר"א והנה בסוף כאשר לא רצה ללכת לקראת נחשים לא רצה בלעם שיהיה בלק מעלה בקרבנותיו שלא יפגל במחשבתו ולכך אמר הכתוב (פסוק ל) ויעל פר ואיל במזבח וירמוז לבלעם הנזכר ויתכן שבלק העלה אותם כי לפייס דעתו עשה כן והוא לא היה עוד חפץ בהם
@44 **ויקר אלהים אל בלעם** . בעבור שלא היה האיש הזה מגיע למעלת הנבואה על כן יאמר בו כלשון הזה כי עתה בא אליו דבור השם דרך מקרה לכבוד ישראל ולכך אמר בו (לעיל כב כ) ויבא אלהים אל בלעם כי הלשון הזה לא יאמר בנביאים רק במי שלא בא במדרגה ההיא וכן ויבא אלהים אל אבימלך (בראשית כ ג) ויבא אלהים אל לבן (שם לא כד) ואפשר שפירושו ביאת הרצון בדבור מן העליון אל השכלים אשר יחלימו כי גם בלעם ביום נופל ותרדמה נפלה עליו וגלוי עינים וטעם ויקר אלהים וגו' ויאמר אליו כי כאשר קרה לבלעם כמקרים אשר יקרו לאנשי רוח הקודש בהתבודדם שחלף רוח על פניו תסמר שערת בשרו פחד קראתהו ורעדה ורוב עצמותיו הפחיד והודו נהפך עליו למשחית והוא נופל על פניו ארצה אז אמר את שבעת המזבחות ערכתי והוא דרך תפלה כאשר פירשתי (פסוק א) והשם לא שמע אליו על כוונתו ואמר לו כה תדבר
@45 **וטעם וישם ה' דבר בפי בלעם** . יש מפרשים כי לא ידע בלעם בדברים אך השם מלא אותו דברים ואמר לו שוב אל בלק וכה תדבר כי יצאו הדברים מפיך ואולי כן דעת רבותינו שאמרו (תנחומא בלק יב) עיקם את פיו ופיקמו כאדם שקובע מסמר בלוח ר' אליעזר אומר מלאך היה מדבר ר' יהושע אומר וכו' ואינו נכון בעיני בעבור אמרו (להלן כד ד) שומע אמרי אל אשר מחזה שדי יחזה אבל טעם "וישם" הלמוד שלמדו הדברים שיגרוס אותם בפיו ולא ישכח ולא יפיל מהם דבר כטעם ולמדה את בני ישראל שימה בפיהם (דברים לא יט) וכן כי על פי אבשלום היתה שומה ( יג לב)
@49 **כי מראש צורים אראנו** . הטעם בעבור שהעלהו במות בעל לראותו אמר מראש צורים ומן הגבעות אני מביט ורואה אותו כי ישכון לבדו ואין עמו גוי אחר שיחשב הוא אליו כמו שיתקבצו עמים רבים ואומות שונות להיות מחנה אחת אבל אלו כולם תורה אחת ומשפט אחד להם וגוי אחד הם וישכון בדד בשם יעקב וישראל ועל כן הזכיר (פסוק ז) ארה לי יעקב וזועמה ישראל כי הזכיר להם שמם הנכבד ושמות אבותם לאמר שהם עם לבדד ושמות נאות להם מאבותם כי בלק לא היה מזכיר לו שם ישראל רק אמר (לעיל כב ה) עם יצא ממצרים כמתנכר בהם שלא ידע אותם שהיה כפוי טובת אביהם והכוונה לומר כי כאשר אני רואה אותו עתה שוכן לבדו כן ישכון לעולמים בטח בדד עין יעקב והוא יהיה לראש לעולם ואין אומה שתתגבר עליו ולא שיטפל הוא אליהם
@50 **מי מנה עפר יעקב** . יאמר אני רואה אותם מראש הרים שוכנים לבדד ולא אוכל למנות אותם כי הם לבדם כעפר הארץ אשר לא יוכל איש למנות את עפר הארץ וגם רובע ישראל למחנות הדגלים הארבעה לא אוכל למנות יתנבא עליהם שירבו ולא ימעטו ויהיו תמיד הם לבדם זרע יעקב כחול הים אשר לא ימד ולא יספר וזה דעת אונקלוס ברבע ישראל גם נכון הוא שיהיה כמו ארחי ורבעי זרית (תהלים קלט ג) מן לא תרביע כלאים (ויקרא יט יט) כלשון וממי יהודה יצאו (ישעיהו מח א) ואמר תמת נפשי מות ישרים ותהי אחריתי כמהו לומר שהן נוחלי גן עדן כי אחרית האדם המות על כן יבקש שימות מות ישרים הם ישראל הנקראים ישורון שיבלו ימיהם בטוב ותהי אחריתי כמוהו כישראל אשר חלקם בחיים ואינם בני גיהנם ואבדון והנה כלל נבואתו בזה הפעם שאין השם חפץ בקללתנו וכי אנחנו עם לבדד חלקו ועמו לא נתערב בגוים ולא נחשב עמהם ואחריתנו טובה בדרך ישר
@56 **ויקר ה' אל בלעם** . עתה לכבוד ישראל עלה האיש הזה להתנבא במדת רחמים בשם הגדול אשר נגלה למשה כי עד עתה נאמר בו ויקר אלהים (פסוק ד) ויבא אלהים (לעיל כב ט) ועתה ידע כי לא יוכל לקללם בשום ענין בעבור כי במדת רחמים יחונן עליהם כי עד עתה כשהיה שומע במדת הדין היה חושב למצוא להם עלה בעון אשר חטאו כענין ויהפך להם לאויב הוא נלחם בם (ישעיהו סג י) או שתבא עליהם רעה מאת ה' לא ינצלו ממנה במדת הדין וזה טעם וירא בלעם כי טוב בעיני ה' לברך את ישראל (להלן כד א) כי גם ה' יתן הטוב בברכה והמשכיל יבין
@61 **לא הביט און ביעקב** . יחזור אל האל הנזכר (פסוק יט) יאמר שלא הביט השם און ושקר ביעקב ולא ראה בהם עמל וכעס שיעשו לפניו ועל כן הוא עמם ותרועת מלכותו בהם כי יריע אף יצריח על אויביהם יתגבר זה דעת ר"א ונכון הוא ויתכן עוד לפרש כי "און" במקום הזה כמו תחת און ראיתי אהלי כושן (חבקוק ג ז) ועמל כמוהו וכן תחת לשונו עמל ואון (תהלים י ז) כזב ושקר כי הדבר שלא יהיה ולא יבא כי שקר הוא יקרא און ועמל בעבור שלא יגיע לאדם ממנו רק העמל יאמר הנה ברך לקחתי וברך ולא אשיבנה כי לא הביט אדם ביעקב ולא ראה איש בישראל און ודבר כזב אין בטחונם שקר ואין תוחלתם נכזבת אבל כל ברכותיהם ובטחונם יתקיימו לעולם כלשון הנה כה מבטנו (ישעיהו כ ו) וחתו ובשו מכוש מבטם (שם פסוק ה) וכן ולא הבטתם אל עושיה ויוצרה מרחוק לא ראיתם (שם כב יא) ענין בטחון ותקוה ואמר הטעם כי ה' אלהיו עמו אשר לא יכזב ולא ינחם ותרועת מלך גבור בו שלא ינוצח לעולם כי בהוציאו אותם ממצרים הנה לו תוקף גדול כתועפות ראם על כל בהמה ואיך לא יתקיימו כל ברכותיהם ואין בהם נחש וקסם
@63 **כי לא נחש ביעקב** . אינם צריכים לנחש וקסם שיאמר ליעקב וישראל מה פעל אל ומה גזרותיו במרום אינם מנחשים וקוסמים אלא נאמר להם על פי נביאים מה גזרת המקום או אורים ותומים מגידים להם לשון רש"י והנכון בעיני כי בעבור היותו קוסם ובלק שלח לו (לעיל כב ו) כי ידעתי את אשר תברך בקסמיך מבורך ואשר תאור בהם יואר ושלח לו קסמים על כן אמר לו אין נחש ביעקב להרע או להטיב להם ולא קסם בישראל מזיק או מועיל כי בכל עת יאמר ליעקב ולישראל מה פעל אל בהם כי מפי עליון תצא להם הרעות והטוב לומר כי חלק ה' עמו אינם בממשלת שרים וכוכבי השמים וכסיליהם שיזיק להם אדם בקסם ונחש כגוים וזה כאשר אמר משה (דברים ד יט כ) אשר חלק ה' אלהיך אותם לכל העמים תחת כל השמים ואתכם לקח ה' להיות לו לעם נחלה כאשר פירשתי בסדר אחרי מות (ויקרא יח כה)
@64 **כלביא יקום** . שהוא הגור ואחרי כן יתנשא כאריה ולא ישכון בארצו עד יאכל טרף וישתה דם מלכי כנען כדברי אונקלוס והנה הוסיף עתה בנבואה הזאת השנית להגיד לבלק כבשם הארץ והרגם מלכים אדירים והנה בלק יודע כי ישראל לא ינחלו את ארצו ולפיכך אע"פ שהגיד להם עתה שסופם לנצח מלכי כנען ירצה עוד שיקללם בנצוחו עד שיוכל הוא להתגבר עליהם אולי יוכל להלחם בו ולהכות מהם על כן אמר עוד (פסוק כז) ואקחך אל מקום אחר אולי יישר בעיני האלהים וקבותו לי משם לא שיחזיר אחור ברכתו שכבר הודיעו (פסוק יט) לא איש אל ויכזב ובן אדם ויתנחם אבל חשב הנה הם עתידים לכבוש ארץ כנען שהיא נחלתם ולהרוג מלכיהם אבל אפשר שאתגבר אני עליהם ואכה בו כאשר עשו העמלקי והכנעני היושב בהר ההוא שהכום עד החרמה (לעיל יד מה) וזאת כוונתו מפחדו מהם כאשר הזכיר לזקני מדין (לעיל כב ד) או היה ענינו שיוכל להשיב אליו כל מה שתפסו מיד סיחון מאשר למואב כמו שמפורש בדברי יפתח וכבר הזכרתיו
@71 **ולא הלך כפעם בפעם לקראת נחשים** . כי בפעמים הראשונים היה מנחש ורוצה לקלל אותם בנחש והיה השם בא אליו בדרך מקרה לא בכונתו לנבואה ולא ממעלתו שהגיע אליה ועתה כאשר נאמר לו כי לא נחש ביעקב ולא קסם בישראל להרע או להטיב להם הניח הנחשים ולא הלך כפעם בפעם לקראתם אבל שם אל המדבר פניו אשר ישראל שם שיראה אותם ויכין להם נפשו שיחול עליו הדבור מאת השם כאשר עשה עמו פעמים וכן היה לו על כן אמר ותהי עליו רוח אלהים כי עתה היתה עליו יד ה' כאשר היא לנביאים כמו שאמר (לעיל יא כט) ומי יתן כל עם ה' נביאים כי יתן ה' את רוחו עליהם ואומר (ישעיהו סא א) רוח ה' אלהים עלי ועל כן קרא עצמו עתה (פסוק ד) "שומע אמרי אל" כי נביא הוא ורש"י כתב וישת אל המדבר פניו כתרגומו כי היה הרב מתרגם בו ושוי למדברא דעבדו ביה בני ישראל עגלא אנפוהי ואין בנוסחאות מדוקדקות מתרגומו של אונקלוס כן אבל הוא כתוב בקצתן שהוגה בהן מן התרגום הירושלמי והעיקר מה שפירשנו ואמר (שם) אשר מחזה שדי יחזה כי ראה עתה באיספקלריא המאירה כנביאים הראשונים שאמר בהם (שמות ו ג) וארא אל אברהם אל יצחק ואל יעקב באל שדי או במדרגה למטה מהם כי מחזה שדי איננו שדי והנה הם יראו באל שדי והוא יחזה במחזה של שדי והנה היו שתי מדרגות למטה מהם וע"כ קרא עצמו "גלוי עינים" שהיא מדרגת בני הנביאים כמו שנאמר (מלכים ב ו כ) ה' פקח את עיני וגו' וכבר נאמר כן בבלעם עצמו בראיית המלאך (לעיל כב לא) ויגל ה' את עיני בלעם ולא תחשוב בזה זולת מה שפירשנו מפני מאמר רבותינו שאמרו בספרי (ברכה לט) ולא קם נביא עוד בישראל כמשה בישראל לא קם אבל באומות העולם קם ואיזה זה בלעם אלא הפרש יש בין נבואת משה לנבואת בלעם משה לא היה יודע מה מדבר עמו ובלעם היה יודע מה מדבר עמו שנאמר נאום שומע אמרי אל משה לא היה יודע מתי מדבר עמו שנאמר (לעיל ז פט) מדבר אליו ובלעם היה יודע מתי מדבר עמו שנאמר ויודע דעת עליון משה היה מדבר עמו מעומד שנאמר (דברים ה כח) ואתה פה עמוד עמדי ובלעם היה מדבר עמו שהוא נופל שנאמר נופל וגלוי עינים משל לטבחו של מלך יודע כמה הוצאות יוצאות למלך על שולחנו וביאור ענין הברייתא הזו מפני שאמר הכתוב (שם לד י) לא קם נביא עוד בישראל כמשה אשר ידעו ה' פנים אל פנים ודרשו רבותינו שאינו בא לספר במעלה אשר לנבואת משה על נבואת שאר הנביאים שכבר הודיע אותנו מעלתו עליהם בשני מקומות בפסוק וארא אל אברהם אל יצחק ואל יעקב באל שדי ושמי ה' לא נודעתי להם (שמות ו ג) ובפסוק אם יהיה נביאכם וגו' (לעיל יב ו) אבל עתה לא דבר על משה שידע הוא את השם כענין שנאמר (שמות לג יג) הודיעני נא את דרכיך ואדעך שלא אמר הכתוב "אשר ידע את השם פנים אל פנים" אבל אמר "אשר ידעו" כי ידבר על ביאור הנבואה יאמר כי למשה רבינו תבא מבוארת כמדבר אל חברו פנים אל פנים שמודיעו דבריו וכוונתו עד שיכיר בפניו שהבין דבריו וכוונתו באמירה ובהכרת רצונו בפניו ואמרו כי לבלעם היה זה בעת שנבא לכבוד ישראל שעמד על דברי ה' ועל רצונו וחפצו בכל הענין העתיד לבא לישראל ואף על פי כן יש הפרש בין נבואת משה לבלעם כי משה לא היה יודע מה מדבר עמו באיזה ענין באיזה מצוה יצונו אבל היה הוא מוכן בכל עת לדבור והיה הקב"ה מצוה אותו כפי הרצון לפניו אבל בלעם היה מכוין ומחשב בדבר ההוא שהוא חפץ בו והולך ומתבודד ומכין נפשו להיות עליו הרוח אולי יקרה ה' לקראתו כאשר הוא מפורש בכאן ויודע שאם יחול עליו בענין ההוא אשר חשב ידבר עמו לא בענין אחר ומשה לא היה יודע מתי ידבר עמו כי לא היה אליו עת קבוע לדבור אבל בכל עת שיחפוץ משה ויכוין לבו לדבור היה מדבר עמו כמו שאמר (לעיל ט ח) עמדו ואשמעה מה יצוה ה' וכן בכל עת שיהיה לפניו יתעלה הרצון להיות מצוה אותו מאהל מועד וישמע את הקול מדבר אליו אבל בלעם היה מכוין את השעה שיהיה לו הדבור ולא תנוח עליו הרוח אלא באותה השעה אולי היא השעה יזכירו רבותינו במסכת ברכות (ז) ובמסכת סנהדרין (קה) שהיה מקלל בה ובה היה חל עליו הרוח לא בעת אחרת לעולם וכן ענין העמידה מעלה למשה והנפילה בבלעם פחיתות שלא יסבול נבואה כענין שנאמר (דברים ה כב כד) אם יוספים אנחנו לשמוע את קול ה' אלהינו עוד ומתנו וגו' קרב אתה ושמע ואמרו משל לטבחו של מלך על המדה הראשונה וכוונתם לאמר שהטבח יודע בהוצאת שולחנו של מלך והשר שלו שהוא נאמן בכל ביתו ועומד בסודו לא ידע בהוצאת השולחן והמשל הזה יורה שדעת החכמים לומר שהיה בלעם יודע מעצמו אחרי כוונתו שהשם יאמר לו מה אקוב לא קבה אל (לעיל כג ח) וכל הענין ואחר כן ישמע הדבור במלות ההם אשר חשב בלבו וזה מה שהזכרתי כי היה קוסם ותבואנה העתידות בלבו ועתה בשביל ישראל ישמע בהם גם הדיבור ולפיכך היה מתפאר בעצמו עתה לומר נאם שומע אמרי אל וראיתי הענין הזה השנוי בסיפרי שאמרו בסיגנון אחר בהגדה של במדבר סיני רבה (כ א) ואין לי להאריך והכלל כי כוונתם לומר שנבואת בלעם תבוא אליו במלות מבוארות לו מן הטעם שאמרו שלא יהא פתחון פה לאומות העולם לומר אלו היה לנו נביא כמשה היינו עובדים להקב"ה אבל מדרגת נבואתו למטה משאר הנביאים שהיא במחזה שדי כמו שביארנו וכן אמרו בויקרא רבה (א יג) אין הקב"ה נגלה על נביאי אומות העולם אלא בחצי דבור היך כמה דתימר ויקר אלהים אל בלעם אבל לנביאי ישראל בדבור שלם שנאמר ויקרא אל משה וחצי הדבור תבין עניינו ממה שבארנו
@73 **שתם העין** . לא מצאו מוצא למלה הזאת מן המקרא ואונקלוס אמר דשפיר חזי כמו פתוח העין לשון חכמים (ע"ז סט) כדי שישתום ויסתום כלומר שיפתח הנקב ואולי היא מלה מורכבת מן שיתי אותותי אלה (שמות י א) שתוי מה הגבר שישיג לכל מה שישית עינו
@77 **וירם מאגג מלכו** . מלך הראשון שלהם יכבוש את אגג מלך עמלק נקרא שמו טרם הולידו דומה לו לכורש אשר החזקתי בימינו (ישעיהו מה א) הנה בן נולד לבית דוד יאשיהו שמו (מלכים א יג ב) ויצחק (בראשית יז יט) וישמעאל (שם טז יא) ושלמה (דהי"א כב ט) ותנשא מלכותו של יעקב יותר ויותר שיבא דוד ושלמה בנו אחריו לשון רש"י ויפה פירש ויתכן שהיה כל מלך בעם עמלק נקרא אגג כי המלך הראשון אשר שמו עליהם היה שמו כן ונקראו בניו היושבים על כסאו בשמו כדרך רוב המלכים גם היום שנקראים בשם תופסי המלכות וכן המן האגגי (אסתר ח ג) כי היה מזרע המלוכה ההיא כי רחוק הוא שיקרא הנביא שם הרשע בטרם נוצר בבטן וכן "גוג" (יחזקאל לט א) כל נשיא המגוג יקרא כן והנה הוסיף בפעם הזאת השלישית להודיע לבלק כי אהלי יעקב היו טובים רמז מעת היותם שוכני אוהלים עד שינחלו את הארץ ומשכנות ישראל גם כן יהיו טובים אחרי כבוש וחלוק שישכנו בה במשכנות מבטחים וכן תהיה ארצו מלאה כל טוב כגן רוה וכמוצא מים אשר לא יכזבו מימיו וכי ינצח את עמלק בעבור שנלחם בו ויאבד זכרו ותנשא עוד המלכות של ישראל שיהיו בה אחרי כן מלכים אדירים ינשאו מאד ואמר לו שיאכל כל צריו " ועצמותיהם יגרם " רמז להונם וכל אשר להם ואמר שישכנו בה לבטח לא ייראו מכל עם כארי וכלביא שלא יירא פריץ חיות ועתה נואש בלק ממנו שאם ילחם בו יאבד באמת כי כל צריו יאכל כאשר יאכל עמלק בעבור שנלחם בו על כן אמר לו עתה שיברח אל מקומו אין לו חפץ בו
@82 **הלא גם אל מלאכיך** . יתנצל בלעם עתה במה שאמר למלאכיו בשובם אליו טרם שידע מה יוסף ה' דבר עמו אבל אחרי כן הראה שיבא ויקלל עד שהתרה בו המלאך בדרך כאשר פירשתי (לעיל כב כ)
@84 **לכה איעצך** . לפי שרצה לומר פורענות אומתו כדכתיב (פסוק יז) ומחץ פאתי מואב לכך אמר לו "איעצך" כלומר אומר לך לצד אחד דרך עצה שלא ישמעו אחרים לכה איעצך מה לך לעשות ומה היא העצה אלהיהם של אלו שונא זמה הוא וכו' כדאיתא בפרק חלק (סנהדרין קו) תדע שבלעם השיאם עצה זו בזמה שנאמר (להלן לא טז) הן הנה היו לבני ישראל בדבר בלעם אשר יעשה העם הזה לעמך מקרא קצר הוא איעצך להכשילם ואומר לך מה עתידין להרע למואב באחרית הימים לשון רש"י והנכון בעיני שיאמר לו אגיד לך העצה אשר יעץ האלהים שיעשה העם הזה לעמך באחרית הימים מלשון זאת העצה היעוצה על כל הארץ (ישעיהו יד כו) שמעו עצת ה' אשר יעץ על אדום (ירמיהו מט כ) ואמר "איעצך" כי השומע עצה יקרא נועץ והנבואה הזאת לימות המשיח היא כי כל נבואותיו מוסיפות בעתידות מתחלה אמר שהם חלק ה' ונחלתו ובשנית הוסיף כבשם הארץ והרגם מלכיה ובשלישית ראה שבתם בארץ ופרו ורבו על הארץ והעמידם מלך ינצח את אגג ותנשא עוד המלכות שראה דוד מתנשא למעלה וכמו שנאמר ( ה יב) וידע דוד כי הכינו ה' למלך וכי נשא מלכותו בעבור עמו ישראל כלומר בעבור אשר הבטיחם שתנשא מלכותם ועתה בנבואה הזאת הרביעית יוסף לראות ענין המשיח ולכך הרחיק הענין מאד ואמר אראנו ולא עתה אשורנו ולא קרוב (פסוק יז) מה שלא אמר כן בנבואות הראשונות ואמר שזאת עצת ה' שיעץ להיות באחרית הימים
@85 **שומע אמרי אל** . " ו" מחזה שדי יחזה " כאשר עשה בנבואה השלישית והוסיף לקרא עצמו " יודע דעת עליון " והאומר כך "יודע אני דעת פלוני" ירצה לומר שהוא מכיר ממנו מה בלבו הדברים שלא יגיד בפיו וכן זה יכוין לומר שהוא יודע ויאמר עתה מה שיש בדעתו של אל עליון לעשות בעולמו בסוף כל הימים וזה כענין שנאמר (ישעיהו סג ד) כי יום נקם בלבי ואמרו (קהלת רבה יב י) ליבא לפומא לא גלי והנה אמר הכתוב בכאן וישא משלו ויאמר ולא הזכיר שהיה זה בנבואה כאשר הזכיר בשלשה פעמים כי כיון שאמר נאם שומע אמרי אל ומחזה שדי יחזה בידוע כי היתה עליו יד ה' כאשר בפעם השלישית שאמר (פסוק ב) ותהי עליו רוח אלהים וקרא עצמו כן
@87 **דרך כוכב מיעקב** . בעבור כי המשיח יקבץ נדחי ישראל מקצה הארץ ימשילנו לכוכב הדורך ברקיע מקצה השמים כמו שנאמר בו (דניאל ז יג) וארו עם ענני שמיא כבר אנש אתה וגו' ואמר שהוא רואה לזמן רחוק שידרוך כוכב מקצה השמים ויקום ממנו שבט מושל ומחץ פאתי מואב וקרקר כל בני שת בן אדם שהוא אבי כל האומות והזכיר "פאתי מואב" להודיע לבלק כי עמו לא יפול ביד ישראל עתה אבל באחרית הימים לא ינצל מואב מיד השבט המושל בו וטעם פאתי מואב לומר כי זה השבט יקרקר כל בני שת ולא ינצל מואב מידו אע"פ שהם קצוצי פאה ואין להם שם באומות ולא ילחמו בישראל
@88 **וטעם והיה ירשה שעיר איביו** . שיהיה שעיר ירשה לאויביו או "אויביו" הם אדום ושעיר הנזכרים שהם אויבי יעקב ויהיו ירשה
@89 **וטעם והאביד שריד מעיר** . מכל עיר שלא ישאר שריד מכל עיר שבעולם כי מתחלה אמר (פסוק יז) וקרקר כל בני שת ועתה יאמר שלא ישאיר שריד ופליט והנה נשלמה העצה שהודיע לבלק
@90 **וירא את עמלק** . נסתכל בפורענותו של עמלק ואמר ראשית גוים עמלק הוא קדם את כלם להלחם בישראל וכך תרגם אונקלוס ואחריתו ליאבד בידם תמחה את זכר עמלק (דברים כה יט) לשון רש"י ויתכן כי "וירא" כפשוטו שהיה בראש הפעור הנשקף על פני הישימון והביט כנגד ארץ עמלק היושב בהר ההוא ואמר כי הוא עתה ראשית גוים כי בראש העמים יחשב כי גבורים היו ואנשי חיל למלחמה ולולי כן לא עלה בלבו לבא להלחם בישראל ולא הוצרך משה לבחור אנשים ולתפלה ולנשיאות כפיו לחולשתו ובנה מזבח וקרא שמו ה' נסי (שמות יז טו) כי חשבה לנס גדול ולכך אמר זה כי הוא ראשית העמים ואחריתו יאבד יותר מכולם כמו שאמר (שם פסוק יד) כי מחה אמחה את זכר עמלק מתחת השמים וכן ראשית שמנים (עמוס ו ו) המשובח שבהם שהוא נמנה ראשונה וכן ראשית החרם (שמואל א טו כא) לראש ולקצין (שופטים יא יא) בשמים ראש (שמות ל כג)
@91 **וטעם וירא את הקיני** . גם כן שראה את ארצם כי עם עמלק היה יושב (שמואל א טו ו) וישא משלו ויאמר להם בדרך עצה איתן מושבך ושים בסלע קנך כלומר שים מושבך במקום איתן ובסלע קנך שתסור ותרד מתוך עמלק פן תספה עמו ותשים בסלע איתן מושבך עם ישראל כמו שאמר (שופטים א טז) ובני קיני חותן משה עלו מעיר התמרים את בני יהודה וגו' ואמר כי אם יהיה לבער קין כלומר ואל תפחד בבואך בישראל כי אם תהיה לבער עמהם כי כאשר יגלו את ישראל יבערו את הארץ מיושב עד מה אשור תשבך לא ישבה אותך לעולם כי תגאל מידו עם ישראל ואם תהיה עם עמלק תהי אחריתך עדי אובד עמהם וכן עד מה ה' תאנף לנצח (תהלים עט ה) עד מה כבודי לכלימה (שם ד ג) כמו עד מתי או שיבאו לגודל דבר כגון מה אמולה לבתך (יחזקאל טז ל) מה אמך לביא (שם יט ב) כלומר עד מה יעלה ויגדל השבי אשר אשור תשבך איננו נחשב לך כלום כי לא תאבד כאשר היית אובד בעמלק ולכן נשא משלו על אשור שיבא עת ארצו גם הוא ואין מי שינצל מיום ה' הגדול והנורא על כל העמים שיבואו צים מיד כתים והם הרומיים וענו את אשור הנזכר וענו עבר שהם ישראל לומר שיענו המגלים והגולים וגם הוא עם כתים עדי אובד בסוף
@96 **לזנות אל בנות מואב** . על ידי עצת בלעם כדאיתא בחלק (סנהדרין קו) לשון רש"י ובאמת שהזנות לא היתה מזמת הנשים כי בעצת אנשיהן וגדוליהם נעשה ומזקני מדין היה להם שנאמר במדינים (להלן פסוק יח) כי צוררים הם לכם בנכליהם אשר נכלו לכם על דבר פעור כי נכלו להם בזמה להדיחם אחר בעל פעור ולכן יתכן שהיה בלעם בעצה שהוא גדול עצתם ודעתו להרע לישראל ועשה בזה כל יכולתו כמו שנאמר (דברים כג ו) ולא אבה ה' אלהיך לשמוע אל בלעם ועל כן הרגוהו בחרב אבל על דרך הפשט לא הזכיר הכתוב העצה בכאן רק במה שאמר אחרי כן (להלן לא טז) הן הנה היו לבני ישראל בדבר בלעם כאשר לא הזכיר עצת זקני מדין רק במה שאמר כי צוררים הם לכם אחרי המעשה בעת הנקמה יזכיר מאין יצאה להם הרעה ויאמר כי לא היה המעשה ביצר הזמה אשר הוא באנשים ובנשים מנעוריהם בטבעם רק עצה רעה להדיחם ולפיכך ראוי לנקמה גדולה כי פירוש "לכה איעצך אשר יעשה העם הזה לעמך באחרית הימים" הוא באמת כאשר פירשתי (לעיל כד יד) ויתכן עוד על דרך הפשט כי בלק בתחלה היה חפץ לקללם ולהלחם בהם ולא יתן אותם לבא בגבולו כלל וכאשר אמר לו בלעם כי לא יוכל להם והודיעו שלא יחריבו ארצו ועמו רק באחרית הימים אז הוציא לחם ויין בערבות מואב ופתה אותם כאוהב להם וזהו "בדבר בלעם" כי בעבור דבריו עשו כן אבל מפני שהיה חפצו לקללם ונשכר לבלק בכך לולי צדקות ה' אשר הפך את הקללה לברכה על כן הרגוהו בחרב כי השוכר והשכיר שניהם נענשו כמו שאמר (דברים כג ה) ואשר שכר עליך את בלעם בן בעור וגו'
@100 **הרגו איש אנשיו** . כל אחד ואחד מדייני ישראל היה הורג שנים ודייני ישראל שבעה רבוא ושמונת אלפים כדאיתא בסנהדרין (יח) לשון רש"י ולא הבינותי זה שיהיו הנצמדים שנדונו רבים מט"ו רבוא רובע ישראל וחלילה ואין דיני נפשות בדיין אחד אלא בסנהדרין של עשרים ושלשה ועדיין יהיו מרובין ואין החסרון בחומש הפקודים (במדבר כו נא) כל כך וכל הנצמדים מתו דכתיב (דברים ד ג) כי כל האיש אשר הלך אחרי בעל פעור השמידו ה' אלהיך מקרבך אבל פירוש "איש אנשיו" שיהרגו השופטים כל הנצמדים כל ב"ד וב"ד ידון את שבטו ואת אלפו כדכתיב (שם א טו) ואקח את ראשי שבטיכם ואתן אותם ראשים עליכם שרי אלפים ושרי מאות ושוטרים לשבטיכם אחר כך מצאתי בגמרא ירושלמי בפרק חלק (סנהדרין פ"י ה"ב) כך וכמה הם שופטי ישראל שבע רבוא ושמונת אלפים ושש מאות אמר להן כל חד מנכון יקטלון תרין נמצאו ההרוגים חמש עשרה רבוא ושבעת אלפים ומאתים אם כן נאמר לדעתם שנתרבו ישראל בין מנין למנין הרבה מאד והנכון בעיני בענין הפרשה כי מתחלה נאמר (בפסוק ג) ויצמד ישראל לבעל פעור ויחר אף ה' בישראל כי יצא הקצף מלפני ה' החל הנגף והשם ברחמיו אמר למשה שישפטו השופטים ויתלו הנצמדים ולא יספה האף צדיק עם רשע ומשה צוה כן לשופטים וכאשר נאספו כל העדה פתח אהל מועד לעשות כדבר משה ועוד הנגף הווה בהם והנה העז השמעוני הזה ויקרב אל אחיו את המדינית למרוד במשה ובשופטים ולעשות כן בפרהסיא כי נשיא וגדול היה ורבים עוזרים לו או כמו שאמרו רבותינו (סנהדרין פב) שאמרו לו שבטו אנו נדונין מיתה ואתה שותק והנה התחילו משה והשופטים לבכות ויעמד פנחס ויפלל ותעצר המגפה ולא נדון אחד מכל העם ביד השופטים כי השם אמר (פסוק ד) והוקע אותם וישוב חרון אף ה' מישראל וכבר שב אפו ולכך לא הזכיר הכתוב "ויעשו כן שופטי ישראל" ויתכן שתהיה כוונת האגדה הנזכרת לומר שיהיו ההרוגים לפי המצוה יותר מחמש עשרה רבוא לומר שהיו החוטאים רבים אבל חסך עליהם ענין פנחס והנה נשארו מן הנצמדים והקב"ה השמידם אחר כן טרם עברם את הירדן זהו שכתוב (דברים ד ג ד) כי כל האיש אשר הלך אחרי בעל פעור השמידו ה' אלהיך מקרבך ואתם הדבקים בה' אלהיכם חיים כלכם היום
